import{M as e,O as t,c as n,d as r,h as i,m as a,p as o}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as s}from"./app-CMHU_KuF.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S06/S06E15.html","title":"S06E15 The One That Could Have Been","lang":"zh-CN","frontmatter":{"title":"S06E15 The One That Could Have Been","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":136},"git":{"createdTime":1780654155000,"updatedTime":1785479208000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":5}]},"readingTime":{"minutes":76.6,"words":22979},"filePathRelative":"语言/英语/Friends老友记/S06/S06E15.md"}`),l={name:`S06E15.md`};function u(s,c,l,u,d,f){let p=e(`StickyAudio`),m=e(`AudioButton`);return t(),r(`div`,null,[i(p,{src:`/audio/friends-tv/S06/S06E15.mp3`,title:`S06E15 The One That Could Have Been`}),c[0]||=n(`h1`,{id:`the-one-that-could-have-been`,tabindex:`-1`},[n(`a`,{class:`header-anchor`,href:`#the-one-that-could-have-been`},[n(`span`,null,`The One That Could Have Been`)])],-1),c[1]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`本可以`)])],-1),c[2]||=n(`p`,null,`The One That Could Have Been`,-1),c[3]||=n(`blockquote`,null,[n(`p`,null,`那个可能是`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`0.0`,duration:`2.976`}),c[4]||=a(),c[5]||=n(`strong`,null,`Part I Written by:`,-1),c[6]||=a(` Greg Malins & Adam Chase`,-1),c[7]||=n(`blockquote`,null,[n(`p`,null,`格雷格·马林斯和亚当·蔡斯`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2.976`,duration:`3.144`}),c[8]||=o(` <strong>Part II Written by:</strong> David Crane &amp; Marta Kauffman<blockquote><p>David Crane和Marta Kauffman</p></blockquote><p>Parts I &amp; II Transcribed by: Eric Aasen</p><blockquote><p>埃里克·阿森</p></blockquote><p>{Transcriber’s Note: This is an hour-long special episode. Which means that the first part of this episode is episode 615. The second part of this episode is episode 616. Since episodes 615 and 616 are combined into one file, that’s why there is no episode 616 in the season 6 table of contents and the numbers jump from episode 615 to 617.}</p><blockquote><p>{抄写者注：这是一个小时长的特别集。这意味着这一集的第一部分是第615集。这一集的第二部分是第616集。由于第615集和第616集合并到一个文件中，这就是为什么第六季目录中没有第616集，并且数字从第615集跳到第617集的原因。}</p></blockquote><hr><p>🎬 <em>Central Perk, everyone is there as Rachel enters.</em></p><blockquote><p>🎬 <em>中央公园，瑞秋进来时，所有人都在那里。</em></p></blockquote>`,11),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`6.12`,duration:`6.72`}),c[9]||=a(),c[10]||=n(`strong`,null,`Rachel Green:`,-1),c[11]||=a(` Hey, you guys! Guess what? Barry and Mindy are getting a divorce!`,-1),c[12]||=n(`blockquote`,null,[n(`p`,null,`嘿，你们这些家伙！猜猜怎么着？巴里和明蒂要离婚了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`12.84`,duration:`1.8`}),c[13]||=a(),c[14]||=n(`strong`,null,`Monica Geller:`,-1),c[15]||=a(` Oh my God!`,-1),c[16]||=n(`blockquote`,null,[n(`p`,null,`哦，我的天啊！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`14.64`,duration:`0.792`}),c[17]||=a(),c[18]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[19]||=a(` Wow!`,-1),c[20]||=n(`blockquote`,null,[n(`p`,null,`哇！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`15.432`,duration:`2.328`}),c[21]||=a(),c[22]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[23]||=a(` (To Ross) What is the matter with you?!`,-1),c[24]||=n(`blockquote`,null,[n(`p`,null,`（对罗斯）你怎么了？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`17.76`,duration:`2.088`}),c[25]||=a(),c[26]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[27]||=a(` No! Barry and Mindy.`,-1),c[28]||=n(`blockquote`,null,[n(`p`,null,`不！巴里和明蒂。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`19.848`,duration:`6.192`}),c[29]||=a(),c[30]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[31]||=a(` Oh sorry, I hear divorce I immediately go to Ross. (To Rachel) Who-who’s Barry and Mindy?`,-1),c[32]||=n(`blockquote`,null,[n(`p`,null,`哦，对不起，我听说离婚后我马上去找罗斯。（对瑞秋）谁是巴里和明蒂？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`26.04`,duration:`4.512`}),c[33]||=a(),c[34]||=n(`strong`,null,`Rachel Green:`,-1),c[35]||=a(` Barry was the guy that I was almost married and Mindy was my best friend.`,-1),c[36]||=n(`blockquote`,null,[n(`p`,null,`巴里是我差点结婚的那个人，明迪是我最好的朋友。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`30.552`,duration:`3.24`}),c[37]||=a(),c[38]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[39]||=a(` Ohh-oh, wasn’t he cheating on you with her?`,-1),c[40]||=n(`blockquote`,null,[n(`p`,null,`哦，哦，他不是在欺骗你吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`33.792`,duration:`5.136`}),c[41]||=a(),c[42]||=n(`strong`,null,`Rachel Green:`,-1),c[43]||=a(` Yeah, but that just means that he was falling asleep on top of her instead of me.`,-1),c[44]||=n(`blockquote`,null,[n(`p`,null,`是的，但那只是意味着他睡在她身上而不是我身上。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`38.928`,duration:`2.304`}),c[45]||=a(),c[46]||=n(`strong`,null,`Monica Geller:`,-1),c[47]||=a(` Why did they get divorced?`,-1),c[48]||=n(`blockquote`,null,[n(`p`,null,`他们为什么离婚？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`41.232`,duration:`11.904`}),c[49]||=a(),c[50]||=n(`strong`,null,`Rachel Green:`,-1),c[51]||=a(` Well, apparently she caught him cheating on her with someone else. Isn’t that sad? (Giggles.) God, could you imagine if I actually married him?! I mean how different would my life be?`,-1),c[52]||=n(`blockquote`,null,[n(`p`,null,`很明显，她抓到他和别人偷情了。这不是很伤心吗？（咯咯笑）天啊，你能想象如果我真的嫁给了他吗？！我的意思是我的生活会有多不同？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`53.136`,duration:`5.88`}),c[53]||=a(),c[54]||=n(`strong`,null,`Ross Geller:`,-1),c[55]||=a(` I know what you mean, I’ve always wondered how different my life would be if-if I’d never gotten divorced.`,-1),c[56]||=n(`blockquote`,null,[n(`p`,null,`我知道你的意思，我一直想知道如果我不离婚，我的生活会有多不同。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`59.016`,duration:`1.152`}),c[57]||=a(),c[58]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[59]||=a(` Which time?`,-1),c[60]||=n(`blockquote`,null,[n(`p`,null,`什么时候？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`60.168`,duration:`7.104`}),c[61]||=a(),c[62]||=n(`strong`,null,`Ross Geller:`,-1),c[63]||=a(` The first time! No seriously, imagine if Carol hadn’t realized she was a lesbian.`,-1),c[64]||=n(`blockquote`,null,[n(`p`,null,`第一次！不，说真的，想象一下如果卡萝没有意识到她是个女同性恋。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`67.272`,duration:`4.176`}),c[65]||=a(),c[66]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[67]||=a(` (starts to imagine it) I can’t. I keep seeing it the good way.`,-1),c[68]||=n(`blockquote`,null,[n(`p`,null,`（开始想象）我不能。我一直以一种好的方式看待它。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`71.448`,duration:`10.872`}),c[69]||=a(),c[70]||=n(`strong`,null,`Ross Geller:`,-1),c[71]||=a(` I’d bet I’d still be doing my kara-tay. (That’s karate, he’s just saying it that way.) Towards the end of our marriage I was doing a lot of kara-tay as a way of releasing the tension from y’know, not doing anything else physical.`,-1),c[72]||=n(`blockquote`,null,[n(`p`,null,`我敢打赌我还是会练卡拉泰拳。（那是空手道，他就是这么说的。）在我们婚姻结束的时候，我练了很多卡拉泰拳，以此来缓解紧张情绪，不做任何其他的身体动作。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`82.32`,duration:`3.6`}),c[73]||=a(),c[74]||=n(`strong`,null,`Chandler Bing:`,-1),c[75]||=a(` Maybe the problem was you were pronouncing it kara-tay.`,-1),c[76]||=n(`blockquote`,null,[n(`p`,null,`也许问题是你发的是卡拉·泰。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`85.92`,duration:`5.928`}),c[77]||=a(),c[78]||=n(`strong`,null,`Monica Geller:`,-1),c[79]||=a(` And what if I was still fat? (To Chandler) Well, you wouldn’t be dating me, that’s for sure.`,-1),c[80]||=n(`blockquote`,null,[n(`p`,null,`如果我还胖呢？（对钱德勒）嗯，你肯定不会跟我约会。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`91.848`,duration:`1.968`}),c[81]||=a(),c[82]||=n(`strong`,null,`Chandler Bing:`,-1),c[83]||=a(` Sure I would!`,-1),c[84]||=n(`blockquote`,null,[n(`p`,null,`我当然会的！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`93.816`,duration:`2.424`}),c[85]||=a(),c[86]||=n(`strong`,null,`All:`,-1),c[87]||=a(` (simultaneously) Oh yeah! Come on! Yeah right!`,-1),c[88]||=n(`blockquote`,null,[n(`p`,null,`（同时）哦，是的！来吧！是的，对！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`96.24`,duration:`3.624`}),c[89]||=a(),c[90]||=n(`strong`,null,`Chandler Bing:`,-1),c[91]||=a(` What, you guys really think that I’m that shallow?`,-1),c[92]||=n(`blockquote`,null,[n(`p`,null,`什么，你们真的认为我那么肤浅吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`99.864`,duration:`3.552`}),c[93]||=a(),c[94]||=n(`strong`,null,`Ross Geller:`,-1),c[95]||=a(` No, I just think Monica was that fat.`,-1),c[96]||=n(`blockquote`,null,[n(`p`,null,`不，我只是觉得莫妮卡那么胖。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`103.416`,duration:`6.552`}),c[97]||=a(),c[98]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[99]||=a(` Hey, imagine if I never got fired off Days Of Our Lives! (Closes his eyes to do so.) Oh-hey, there’s Carol again!`,-1),c[100]||=n(`blockquote`,null,[n(`p`,null,`嘿，想象一下，如果我在我们的生活中从未被解雇过！（闭上眼睛）哦，嘿，卡萝又来了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`109.968`,duration:`13.776`}),c[101]||=a(),c[102]||=n(`strong`,null,`Chandler Bing:`,-1),c[103]||=a(` What if I had had the guts to quit my job? I’d probably be writing for the New Yorker, getting paid to be funny. But my job’s fun too! I mean tomorrow, I-I don’t have to wear a tie.`,-1),c[104]||=n(`blockquote`,null,[n(`p`,null,`如果我有勇气辞职怎么办？我可能会为《纽约客》写文章，拿薪水来搞笑。但我的工作也很有趣！我是说，明天，我不必打领带了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`123.744`,duration:`2.832`}),c[105]||=a(),c[106]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[107]||=a(` What if I had taken that job at Merrill Lynch?`,-1),c[108]||=n(`blockquote`,null,[n(`p`,null,`如果我在美林做那份工作呢？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`126.576`,duration:`1.44`}),c[109]||=a(),c[110]||=n(`strong`,null,`Ross Geller:`,-1),c[111]||=a(` What?!`,-1),c[112]||=n(`blockquote`,null,[n(`p`,null,`什么？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`128.016`,duration:`1.776`}),c[113]||=a(),c[114]||=n(`strong`,null,`Rachel Green:`,-1),c[115]||=a(` Merrill Lynch?`,-1),c[116]||=n(`blockquote`,null,[n(`p`,null,`美林？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`129.792`,duration:`4.488`}),c[117]||=a(),c[118]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[119]||=a(` Yeah, I had a massage client who worked there and-and he said I had a knack for stocks.`,-1),c[120]||=n(`blockquote`,null,[n(`p`,null,`是的，我有一个按摩客户在那里工作，他说我对股票很在行。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`134.28`,duration:`2.424`}),c[121]||=a(),c[122]||=n(`strong`,null,`Rachel Green:`,-1),c[123]||=a(` Well why didn’t you take the job?`,-1),c[124]||=n(`blockquote`,null,[n(`p`,null,`那你为什么不接受这份工作？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`136.704`,duration:`9.96`}),c[125]||=a(),c[126]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[127]||=a(` Because at that time you see, I thought everything that rhymed was true. So I thought y’know that if I’d work with stocks, I’d have to live in a box, and only eat lox, and have a pet fox.`,-1),c[128]||=n(`blockquote`,null,[n(`p`,null,`因为当时你知道，我认为押韵的一切都是真的。所以我想你知道，如果我要做股票，我就得住在一个盒子里，只吃鲑鱼，养一只宠物狐狸。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`146.664`,duration:`4.92`}),c[129]||=o(` <strong>Ross Geller:</strong> Hey, do you guys think that if all those things happened, we’d still hang out?<blockquote><p>嘿，你们认为如果所有这些事情都发生了，我们还会在一起吗？</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><p>{Transcriber’s note: This is where the opening credits are, but they’re not the usual opening credits. Oh no! These credits are based on the world that would have been created had all of the above actually happened. It starts out with all of them at the fountain sitting on the couch as Fat Monica runs up and sits on the arm of the couch, tilting the whole thing towards her. It then goes on to show Rachel’s still a shop-aholic and with Barry. Fat Monica is sweating while cooking and dancing while eating a donut. Phoebe as the Wall Street shark smoking while on two cell phones. Then they’re dancing in the fountain. Joey entering as Dr. Drake Remoray and meeting a groupie. Chandler trying to write as a bird does its business on his shoulder and falling asleep while typing. Ross doing some kara-tay and trying to get Carol into bed. And finally, some more dancing in the fountain, them all flexing, and the turning out the lamp and shutting off all the lights bit from the first season. Just remember one thing, this is an alternate universe. Everything from every other episode doesn’t apply, for instance, Ross and Rachel have no history. And in fact have not seen each other in years in this world.}</p><blockquote><p>{抄写者注：这是开场白的位置，但它们不是通常的开场白。哦，不！这些开场白是基于如果上述所有事情都发生的话本该创造的世界。开始时，所有开场白都坐在沙发上的喷泉旁，胖莫妮卡跑过来坐在沙发的扶手上，倾斜着t他把整件事都告诉了她。接着，这件事显示瑞秋仍然是一个购物狂，和巴里在一起。胖莫妮卡一边做饭一边大汗淋漓，一边吃着甜甜圈一边跳舞。菲比在两部手机上一边抽烟，一边在喷泉里跳舞。乔伊以德雷莫雷博士的身份进来，遇到了一个追星族。钱德勒试图写作就像鸟儿在肩上做自己的事，一边打字一边睡着。罗斯做卡拉·泰，试着让卡萝上床。最后，在喷泉里又跳了一些舞，他们都在挠曲，第一季开始关灯关灯。记住一件事，这是一个交替的宇宙e、 其他每一集的所有内容都不适用，例如，罗斯和瑞秋没有任何历史。事实上，他们在这个世界上已经多年没有见面了。}</p></blockquote><hr><p>🎬 <em>A newsstand, Ross is buying a magazine and gets in line behind a woman.</em></p><blockquote><p>🎬 <em>一个报摊，罗斯正在买一本杂志，在一个女人后面排队。</em></p></blockquote>`,11),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`151.584`,duration:`3.648`}),c[130]||=a(),c[131]||=n(`strong`,null,`Ross Geller:`,-1),c[132]||=a(` (recognizing her) Oh my God! Rachel Green?`,-1),c[133]||=n(`blockquote`,null,[n(`p`,null,`（认出她）哦，天哪！瑞秋·格林？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`155.232`,duration:`1.776`}),c[134]||=a(),c[135]||=n(`strong`,null,`Rachel Green:`,-1),c[136]||=a(` (gasps) Rob Tillman!`,-1),c[137]||=n(`blockquote`,null,[n(`p`,null,`（喘息）罗布·蒂尔曼！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`157.008`,duration:`3.984`}),c[138]||=a(),c[139]||=n(`strong`,null,`Ross Geller:`,-1),c[140]||=a(` No-no. It’s-it’s me, Ross!`,-1),c[141]||=n(`blockquote`,null,[n(`p`,null,`不，不，是我，罗斯！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`160.992`,duration:`3.864`}),c[142]||=a(),c[143]||=n(`strong`,null,`Rachel Green:`,-1),c[144]||=a(` Oh, I’m sorry. Ross Tillman.`,-1),c[145]||=n(`blockquote`,null,[n(`p`,null,`哦，对不起，罗斯·蒂尔曼。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`164.856`,duration:`3.096`}),c[146]||=a(),c[147]||=n(`strong`,null,`Ross Geller:`,-1),c[148]||=a(` No, no-no, Ross Geller.`,-1),c[149]||=n(`blockquote`,null,[n(`p`,null,`不，不，罗斯·盖勒。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`167.952`,duration:`2.88`}),c[150]||=a(),c[151]||=n(`strong`,null,`Rachel Green:`,-1),c[152]||=a(` Ohh, of course Monica’s brother!`,-1),c[153]||=n(`blockquote`,null,[n(`p`,null,`哦，当然是莫妮卡的兄弟了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`170.832`,duration:`2.76`}),c[154]||=a(),c[155]||=n(`strong`,null,`Ross Geller:`,-1),c[156]||=a(` Yeah. Right.`,-1),c[157]||=n(`blockquote`,null,[n(`p`,null,`是的，对。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`173.592`,duration:`3.024`}),c[158]||=a(),c[159]||=n(`strong`,null,`Rachel Green:`,-1),c[160]||=a(` Wow! How are you?!`,-1),c[161]||=n(`blockquote`,null,[n(`p`,null,`哇！你好吗？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`176.616`,duration:`2.664`}),c[162]||=a(),c[163]||=n(`strong`,null,`Ross Geller:`,-1),c[164]||=a(` Good-good, I’m-I’m married. (Shows her his ring.)`,-1),c[165]||=n(`blockquote`,null,[n(`p`,null,`很好，我结婚了。（给她看他的戒指。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`179.28`,duration:`2.976`}),c[166]||=a(),c[167]||=n(`strong`,null,`Rachel Green:`,-1),c[168]||=a(` Ohh! Me too!`,-1),c[169]||=n(`blockquote`,null,[n(`p`,null,`哦！我也是！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`182.256`,duration:`2.136`}),c[170]||=a(),c[171]||=n(`strong`,null,`Ross Geller:`,-1),c[172]||=a(` Is-isn’t it the best?`,-1),c[173]||=n(`blockquote`,null,[n(`p`,null,`这不是最好的吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`184.392`,duration:`4.704`}),c[174]||=a(),c[175]||=n(`strong`,null,`Rachel Green:`,-1),c[176]||=a(` Oh, it’s the best! (They both exhale contemplating the joys of marriage.) So, umm how’s Monica?`,-1),c[177]||=n(`blockquote`,null,[n(`p`,null,`哦，这是最好的！（他们都呼气沉思着婚姻的快乐。）那么，嗯，莫妮卡怎么样？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`189.096`,duration:`11.136`}),c[178]||=a(),c[179]||=n(`strong`,null,`Ross Geller:`,-1),c[180]||=a(` Oh really, really great! Yeah! A-actually she’s right down the street, umm, do-do you know what? You should stop bye and say hi.`,-1),c[181]||=n(`blockquote`,null,[n(`p`,null,`哦，真的，真的很好！是的！事实上她就在这条街上，嗯，你知道吗？你应该停下来说声你好。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`200.232`,duration:`2.448`}),c[182]||=a(),c[183]||=n(`strong`,null,`Rachel Green:`,-1),c[184]||=a(` Ohh, I would love too.`,-1),c[185]||=n(`blockquote`,null,[n(`p`,null,`哦，我也很喜欢。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`202.68`,duration:`4.2`}),c[186]||=a(),c[187]||=n(`strong`,null,`Ross Geller:`,-1),c[188]||=a(` Yeah? Oh-oh, she’d be so excited!`,-1),c[189]||=n(`blockquote`,null,[n(`p`,null,`是吗？哦，她会很兴奋的！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`206.88`,duration:`2.856`}),c[190]||=a(),c[191]||=n(`strong`,null,`Rachel Green:`,-1),c[192]||=a(` Ohh! Okay!`,-1),c[193]||=n(`blockquote`,null,[n(`p`,null,`哦！好的！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`209.736`,duration:`1.608`}),c[194]||=a(),c[195]||=n(`strong`,null,`Ross Geller:`,-1),c[196]||=a(` Come on! (They start to leave.)`,-1),c[197]||=n(`blockquote`,null,[n(`p`,null,`快点！（他们开始离开了。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`211.344`,duration:`4.032`}),c[198]||=a(),c[199]||=n(`strong`,null,`Rachel Green:`,-1),c[200]||=a(` Oh wait, don’t you have to pay for your, (looks at his magazine) Busty Ladies?`,-1),c[201]||=n(`blockquote`,null,[n(`p`,null,`哦，等等，你不需要为你的（看他的杂志）胖女人付钱吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`215.376`,duration:`6.432`}),c[202]||=a(),c[203]||=n(`strong`,null,`Ross Geller:`,-1),c[204]||=a(` No, it’s okay. Some-some kid asked me to pick it up for him, but I don’t…`,-1),c[205]||=n(`blockquote`,null,[n(`p`,null,`不，没关系。有个孩子让我帮他拿，但我不…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`221.808`,duration:`2.952`}),c[206]||=a(),c[207]||=n(`strong`,null,`Rachel Green:`,-1),c[208]||=a(` (laughs) Oh yeah? Okay.`,-1),c[209]||=n(`blockquote`,null,[n(`p`,null,`（笑）哦，是吗？好的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`224.76`,duration:`1.512`}),c[210]||=a(),c[211]||=n(`strong`,null,`Ross Geller:`,-1),c[212]||=a(` (putting the magazine back and holding the money for it) Okay.`,-1),c[213]||=n(`blockquote`,null,[n(`p`,null,`（把杂志放回去，把钱拿着）好的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`226.272`,duration:`4.08`}),c[214]||=a(),c[215]||=n(`strong`,null,`Rachel Green:`,-1),c[216]||=a(` But! Don’t you have to give him his money back?`,-1),c[217]||=n(`blockquote`,null,[n(`p`,null,`但是！你不需要把钱还给他吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`230.352`,duration:`9.312`}),c[218]||=a(),c[219]||=n(`strong`,null,`Ross Geller:`,-1),c[220]||=a(` Uh-huh. (Steps to a random kid nearby and hands him his money.) Hey, here you go buddy. Sorry, no porn for you. (To Rachel) Okay, let’s go see Monica!`,-1),c[221]||=n(`blockquote`,null,[n(`p`,null,`嗯。（走到附近一个随机的孩子跟前，递给他钱。）嘿，给你，伙计。对不起，你不能看色情片。（对瑞秋）好吧，我们去看看莫妮卡！`)],-1),c[222]||=n(`hr`,null,null,-1),c[223]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Central Perk, Joey, Fat Monica, and her boyfriend are sitting on the couch. Monica’s boyfriend is getting up to get something. For future reference, for the rest of this episode Monica’s fat, I won’t be calling her Fat Monica throughout.`)],-1),c[224]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`中央公园、乔伊、胖莫妮卡和她的男朋友坐在沙发上。莫妮卡的男朋友正站起来拿东西。为了将来参考，在本集的其余部分，莫妮卡的胖，我不会一直叫她胖莫妮卡。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`239.664`,duration:`3.84`}),c[225]||=a(),c[226]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[227]||=a(` So Monica, still going out with Dr. Boring huh?`,-1),c[228]||=n(`blockquote`,null,[n(`p`,null,`莫妮卡，还是和无聊博士约会？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`243.504`,duration:`4.608`}),c[229]||=a(),c[230]||=n(`strong`,null,`Monica Geller:`,-1),c[231]||=a(` He’s not boring! He’s just-he’s just low key.`,-1),c[232]||=n(`blockquote`,null,[n(`p`,null,`他不无聊！他只是他只是低调而已。`)],-1),c[233]||=n(`p`,null,`Monica's Boyfriend: (returning) Here we go, one Hazelnut Latte. (Hands it to Monica and sits down.)`,-1),c[234]||=n(`blockquote`,null,[n(`p`,null,`（回来）来了，一杯榛子拿铁。（递给莫妮卡坐下。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`248.112`,duration:`1.584`}),c[235]||=a(),c[236]||=n(`strong`,null,`Monica Geller:`,-1),c[237]||=a(` Thanks.`,-1),c[238]||=n(`blockquote`,null,[n(`p`,null,`谢谢。`)],-1),c[239]||=n(`p`,null,`Monica's Boyfriend: Yeah. Y’know, the hazelnut actually not a nut, it’s a seed.`,-1),c[240]||=n(`blockquote`,null,[n(`p`,null,`是的。你知道，榛子实际上不是坚果，而是种子。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`249.696`,duration:`1.512`}),c[241]||=a(),c[242]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[243]||=a(` (not impressed) Wow!!`,-1),c[244]||=n(`blockquote`,null,[n(`p`,null,`（没有印象）哇！！`)],-1),c[245]||=n(`p`,null,`Monica's Boyfriend: Can anyone else name a well known seed that’s been masquerading as a nut?`,-1),c[246]||=n(`blockquote`,null,[n(`p`,null,`还有谁能说出一个伪装成坚果的著名种子的名字吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`251.208`,duration:`2.712`}),c[247]||=a(),c[248]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[249]||=a(` Oh dear God, let me think. (Starts to sarcastically think about it.)`,-1),c[250]||=n(`blockquote`,null,[n(`p`,null,`哦，天哪，让我想想。（开始讽刺地思考。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`253.92`,duration:`1.44`}),c[251]||=a(),c[252]||=n(`strong`,null,`Chandler Bing:`,-1),c[253]||=a(` (entering, depressed) Hey.`,-1),c[254]||=n(`blockquote`,null,[n(`p`,null,`（进来，沮丧地）嘿。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`255.36`,duration:`1.488`}),c[255]||=a(),c[256]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[257]||=a(` Hey.`,-1),c[258]||=n(`blockquote`,null,[n(`p`,null,`嘿。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`256.848`,duration:`3.336`}),c[259]||=a(),c[260]||=n(`strong`,null,`Monica Geller:`,-1),c[261]||=a(` Oh no! What’s the matter?`,-1),c[262]||=n(`blockquote`,null,[n(`p`,null,`哦，不！怎么了？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`260.184`,duration:`7.608`}),c[263]||=a(),c[264]||=n(`strong`,null,`Chandler Bing:`,-1),c[265]||=a(` Oh I just got another rejection letter. They said my writing was funny, just not "Archie Comic funny."`,-1),c[266]||=n(`blockquote`,null,[n(`p`,null,`哦，我刚收到另一封拒绝信。他们说我的写作很有趣，只是不是“阿尔奇滑稽”`)],-1),c[267]||=n(`p`,null,`Monica's Boyfriend: Y’know what honey? I got to get back to the hospital.`,-1),c[268]||=n(`blockquote`,null,[n(`p`,null,`你知道吗，亲爱的？我得回医院了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`267.792`,duration:`1.608`}),c[269]||=a(),c[270]||=n(`strong`,null,`Monica Geller:`,-1),c[271]||=a(` Okay.`,-1),c[272]||=n(`blockquote`,null,[n(`p`,null,`好的。`)],-1),c[273]||=n(`p`,null,`Monica's Boyfriend: (kisses her) Okay.`,-1),c[274]||=n(`blockquote`,null,[n(`p`,null,`（吻她）好的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`269.4`,duration:`1.488`}),c[275]||=a(),c[276]||=n(`strong`,null,`Monica Geller:`,-1),c[277]||=a(` Bye.`,-1),c[278]||=n(`blockquote`,null,[n(`p`,null,`再见。`)],-1),c[279]||=n(`p`,null,`Monica's Boyfriend: Bye-bye. (Gets up to leave.) Oh uh, by the way, the answer is, the Brazil nut. (Exits.)`,-1),c[280]||=n(`blockquote`,null,[n(`p`,null,`再见。（起身离开。）哦，对了，答案是，巴西坚果。（退出）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`270.888`,duration:`3.096`}),c[281]||=a(),c[282]||=n(`strong`,null,`Chandler Bing:`,-1),c[283]||=a(` Was his question what’s more boring than him?`,-1),c[284]||=n(`blockquote`,null,[n(`p`,null,`他的问题是什么比他更无聊？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`273.984`,duration:`6.336`}),c[285]||=a(),c[286]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[287]||=a(` Hey man, look sorry about that Archie thing. Do uh, do you need me to give you some money?`,-1),c[288]||=n(`blockquote`,null,[n(`p`,null,`嘿，伙计，听着，阿尔奇的事很抱歉。你需要我给你一些钱吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`280.32`,duration:`4.368`}),c[289]||=a(),c[290]||=n(`strong`,null,`Chandler Bing:`,-1),c[291]||=a(` Hey, I may have no money, but I still have my pride.`,-1),c[292]||=n(`blockquote`,null,[n(`p`,null,`嘿，我可能没有钱，但我仍然有我的骄傲。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`284.688`,duration:`1.536`}),c[293]||=a(),c[294]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[295]||=a(` Really?`,-1),c[296]||=n(`blockquote`,null,[n(`p`,null,`真的吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`286.224`,duration:`1.344`}),c[297]||=a(),c[298]||=n(`strong`,null,`Chandler Bing:`,-1),c[299]||=a(` Ehh.`,-1),c[300]||=n(`blockquote`,null,[n(`p`,null,`嗯。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`287.568`,duration:`5.256`}),c[301]||=a(),c[302]||=n(`strong`,null,`Monica Geller:`,-1),c[303]||=a(` Maybe Joey doesn’t have to give you the money, TV stars have assistants right?`,-1),c[304]||=n(`blockquote`,null,[n(`p`,null,`也许乔伊不用给你钱，电视明星有助手，对吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`292.824`,duration:`6.384`}),c[305]||=a(),c[306]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[307]||=a(` That’s an idea! (To Chandler) Hey, if I hired an assistant, would-would you take money from her?`,-1),c[308]||=n(`blockquote`,null,[n(`p`,null,`好主意！（对钱德勒）嘿，如果我雇了个助手，你会从她那里拿钱吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`299.208`,duration:`8.088`}),c[309]||=a(),c[310]||=n(`strong`,null,`Monica Geller:`,-1),c[311]||=a(` No Joey! Chandler could be your assistant! See, he could answer all of your fan mail and stuff!`,-1),c[312]||=n(`blockquote`,null,[n(`p`,null,`不，乔伊！钱德勒可能是你的助手！看，他可以回复你所有的粉丝来信之类的！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`307.296`,duration:`5.568`}),c[313]||=a(),c[314]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[315]||=a(` That’s great! That would be great! Let’s do that!`,-1),c[316]||=n(`blockquote`,null,[n(`p`,null,`太好了！那太好了！我们来吧！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`312.864`,duration:`3.84`}),c[317]||=a(),c[318]||=n(`strong`,null,`Chandler Bing:`,-1),c[319]||=a(` I could use the money; it could give me time to write.`,-1),c[320]||=n(`blockquote`,null,[n(`p`,null,`我可以用这笔钱，它可以给我时间写作。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`316.704`,duration:`3.84`}),c[321]||=a(),c[322]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[323]||=a(` Oh right great! Welcome aboard!`,-1),c[324]||=n(`blockquote`,null,[n(`p`,null,`哦，太好了！欢迎登机！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`320.544`,duration:`1.608`}),c[325]||=a(),c[326]||=n(`strong`,null,`Chandler Bing:`,-1),c[327]||=a(` Okay!`,-1),c[328]||=n(`blockquote`,null,[n(`p`,null,`好的！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`322.152`,duration:`8.256`}),c[329]||=a(),c[330]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[331]||=a(` All right! Now hey, I need to use the bathroom. Since I don’t need any assistance in there, take a break!`,-1),c[332]||=n(`blockquote`,null,[n(`p`,null,`好吧！嘿，我要去洗手间。既然我在那里不需要任何帮助，休息一下吧！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`330.408`,duration:`1.656`}),c[333]||=a(),c[334]||=n(`strong`,null,`Chandler Bing:`,-1),c[335]||=a(` All right!`,-1),c[336]||=n(`blockquote`,null,[n(`p`,null,`好吧！`)],-1),c[337]||=n(`p`,null,[n(`em`,null,`(As Joey goes to the bathroom, Corporate Phoebe enters. She’s wearing a business suit and carrying a briefcase.)`)],-1),c[338]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（乔伊去洗手间时，公司的菲比进来了。她穿着西装，提着公文包。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`332.064`,duration:`0.816`}),c[339]||=a(),c[340]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[341]||=a(` (entering) Hey!`,-1),c[342]||=n(`blockquote`,null,[n(`p`,null,`（进来）嘿！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`332.88`,duration:`3.384`}),c[343]||=a(),c[344]||=n(`strong`,null,`Monica Geller:`,-1),c[345]||=a(` Hey Phoebe! Guess what?`,-1),c[346]||=n(`blockquote`,null,[n(`p`,null,`嘿，菲比！你猜怎么着？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`336.264`,duration:`0.744`}),c[347]||=a(),c[348]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[349]||=a(` What?`,-1),c[350]||=n(`blockquote`,null,[n(`p`,null,`什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`337.008`,duration:`3.528`}),c[351]||=a(),c[352]||=n(`strong`,null,`Monica Geller:`,-1),c[353]||=a(` Joey just hired Chandler to be his assistant!`,-1),c[354]||=n(`blockquote`,null,[n(`p`,null,`乔伊刚雇钱德勒做他的助手！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`340.536`,duration:`18.528`}),c[355]||=a(),c[356]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[357]||=a(` Ohh that’s so sweet! (Her cell phone rings.) Oh! Hang on! (Quickly grabs a cigarette and starts to light it as her phone rings.) Hang onnnnnn!!! (Gets the cigarette lighted and answers the phone.) (On phone.) Go!! No! No-no! I said sell when it hits 50! 5-0, it’s a number! It comes after 4-9!! No, it’s okay. It’s okay, you’re allowed one mistake. Just kidding, you are of course fired.`,-1),c[358]||=n(`blockquote`,null,[n(`p`,null,`哦，太好了！（她的手机响了。）哦！等一下！（迅速抓起一支香烟，在她的手机响时开始点烟。）等一下！！！（点燃香烟，接电话。）（打电话。）加油！！不！不！不！我说的是50点后卖出！5-0，这是一个数字！4-9之后就是了！！不，没关系，你可以犯一个错误。开玩笑，你当然被解雇了。`)],-1),c[359]||=n(`p`,null,[n(`em`,null,`(She hangs up as Ross and Rachel enter.)`)],-1),c[360]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（罗斯和瑞秋进来时，她挂断了电话。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`359.064`,duration:`1.728`}),c[361]||=a(),c[362]||=n(`strong`,null,`Ross Geller:`,-1),c[363]||=a(` Hey Mon!`,-1),c[364]||=n(`blockquote`,null,[n(`p`,null,`嘿，妈妈！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`360.792`,duration:`1.488`}),c[365]||=a(),c[366]||=n(`strong`,null,`Monica Geller:`,-1),c[367]||=a(` Hey!`,-1),c[368]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`362.28`,duration:`2.928`}),c[369]||=a(),c[370]||=n(`strong`,null,`Ross Geller:`,-1),c[371]||=a(` Mon, look who I ran into! (Gestures towards Rachel.)`,-1),c[372]||=n(`blockquote`,null,[n(`p`,null,`莫，看我碰到谁了！（对着瑞秋做手势。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`365.208`,duration:`5.28`}),c[373]||=a(),c[374]||=n(`strong`,null,`Monica Geller:`,-1),c[375]||=a(` (gets up and gasps) Oh my God! Rachel!! (Rachel is stunned to see that her long lost friend is still fat.) (Monica goes over and gives Rachel a big bear hug, which is quite easy for her.) You look terrific!`,-1),c[376]||=n(`blockquote`,null,[n(`p`,null,`（站起来喘息）哦，我的天！瑞秋！！（瑞秋看到她失散已久的朋友仍然很胖感到震惊。）（莫妮卡走过去给瑞秋一个大大的熊抱，这对她来说很容易。）你看起来棒极了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`370.488`,duration:`4.176`}),c[377]||=a(),c[378]||=n(`strong`,null,`Rachel Green:`,-1),c[379]||=a(` Ohh, so do you! Did you lose weight? (She’s not quite sure of that one.)`,-1),c[380]||=n(`blockquote`,null,[n(`p`,null,`哦，你也是！你减肥了吗？（她不太确定。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`374.664`,duration:`5.928`}),c[381]||=a(),c[382]||=n(`strong`,null,`Monica Geller:`,-1),c[383]||=a(` You are so sweet to notice! Yes, I lost three and a half pounds!`,-1),c[384]||=n(`blockquote`,null,[n(`p`,null,`你真可爱！是的，我瘦了三磅半！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`380.592`,duration:`4.176`}),c[385]||=a(),c[386]||=n(`strong`,null,`Ross Geller:`,-1),c[387]||=a(` And, and uh, you-you remember my friend Chandler. (Points to him.)`,-1),c[388]||=n(`blockquote`,null,[n(`p`,null,`还有，嗯，你还记得我的朋友钱德勒。（指着他。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`384.768`,duration:`1.44`}),c[389]||=a(),c[390]||=n(`strong`,null,`Chandler Bing:`,-1),c[391]||=a(` Hey.`,-1),c[392]||=n(`blockquote`,null,[n(`p`,null,`嘿。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`386.208`,duration:`1.536`}),c[393]||=a(),c[394]||=n(`strong`,null,`Rachel Green:`,-1),c[395]||=a(` Oh yeah.`,-1),c[396]||=n(`blockquote`,null,[n(`p`,null,`哦，是的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`387.744`,duration:`2.376`}),c[397]||=a(),c[398]||=n(`strong`,null,`Ross Geller:`,-1),c[399]||=a(` And that’s Phoebe over there! (Points to her.)`,-1),c[400]||=n(`blockquote`,null,[n(`p`,null,`那边是菲比！（指着她。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`390.12`,duration:`0.84`}),c[401]||=a(),c[402]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[403]||=a(` Hi!`,-1),c[404]||=n(`blockquote`,null,[n(`p`,null,`嗨！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`390.96`,duration:`7.32`}),c[405]||=a(),c[406]||=n(`strong`,null,`Monica Geller:`,-1),c[407]||=a(` Oh my God, sit down! Sit down! How long as it been since we’ve seen each other?`,-1),c[408]||=n(`blockquote`,null,[n(`p`,null,`哦，天哪，坐下！坐下！我们多久没见面了？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`398.28`,duration:`10.176`}),c[409]||=a(),c[410]||=n(`strong`,null,`Ross Geller:`,-1),c[411]||=a(` (answering it) 1987, the day after Christmas, at Sean McMahon’s party. I played you one of my songs, y’know Interplanetary Courtship Ritual.`,-1),c[412]||=n(`blockquote`,null,[n(`p`,null,`（回答）1987年，圣诞节后的第二天，在肖恩·麦克马洪的派对上。我给你播放了我的一首歌，你知道星际求爱仪式。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`408.456`,duration:`6.912`}),c[413]||=a(),c[414]||=n(`strong`,null,`Rachel Green:`,-1),c[415]||=a(` Oh yeah. Right. So now, are—do you, do you still do music?`,-1),c[416]||=n(`blockquote`,null,[n(`p`,null,`哦，是的，对了。那么现在，你还在做音乐吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`415.368`,duration:`5.664`}),c[417]||=a(),c[418]||=n(`strong`,null,`Ross Geller:`,-1),c[419]||=a(` Sometimes, you should come over (Joey returns from the bathroom) sometime! I’ll play you one of my other…`,-1),c[420]||=n(`blockquote`,null,[n(`p`,null,`有时候，你应该找个时间过来（乔伊从浴室回来）！我给你玩我的另一个…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`421.032`,duration:`5.856`}),c[421]||=a(),c[422]||=n(`strong`,null,`Rachel Green:`,-1),c[423]||=a(` (interrupting him and seeing Joey) Oh my God! Joey Tribbiani from Days of Our Lives, just walked in here!`,-1),c[424]||=n(`blockquote`,null,[n(`p`,null,`（打断他，看到乔伊）哦，我的天！我们生活中的乔伊·特里比亚尼，刚刚走进这里！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`426.888`,duration:`2.76`}),c[425]||=a(),c[426]||=n(`strong`,null,`Monica Geller:`,-1),c[427]||=a(` Rach, he’s a friend of ours.`,-1),c[428]||=n(`blockquote`,null,[n(`p`,null,`瑞秋，他是我们的朋友。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`429.648`,duration:`2.952`}),c[429]||=a(),c[430]||=n(`strong`,null,`Rachel Green:`,-1),c[431]||=a(` (stunned) You are friends with Dr. Drake Remoray?`,-1),c[432]||=n(`blockquote`,null,[n(`p`,null,`（惊呆了）你是德雷克·雷莫雷医生的朋友吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`432.6`,duration:`6.168`}),c[433]||=a(),c[434]||=n(`strong`,null,`Chandler Bing:`,-1),c[435]||=a(` Well it’s kinda hard to be friends with Drake because of his busy schedule and the fact that he’s not real.`,-1),c[436]||=n(`blockquote`,null,[n(`p`,null,`嗯，和德雷克交朋友有点难，因为他的日程很忙，而且他不是真的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`438.768`,duration:`4.128`}),c[437]||=a(),c[438]||=n(`strong`,null,`Ross Geller:`,-1),c[439]||=a(` (To Rachel) Hey-hey, or I could bring my keyboard over here sometime!`,-1),c[440]||=n(`blockquote`,null,[n(`p`,null,`（对瑞秋）嘿嘿，要不我找个时间把键盘带过来！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`442.896`,duration:`3.936`}),c[441]||=a(),c[442]||=n(`strong`,null,`Rachel Green:`,-1),c[443]||=a(` He’s coming over! He’s coming over!`,-1),c[444]||=n(`blockquote`,null,[n(`p`,null,`他过来了！他过来了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`446.832`,duration:`1.584`}),c[445]||=a(),c[446]||=n(`strong`,null,`Monica Geller:`,-1),c[447]||=a(` (getting up) Joey!`,-1),c[448]||=n(`blockquote`,null,[n(`p`,null,`（站起来）乔伊！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`448.416`,duration:`2.232`}),c[449]||=a(),c[450]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[451]||=a(` (holding a plate of what looks like Rice Crispies Treats) I know, here-here!! (Hands her the plate.)`,-1),c[452]||=n(`blockquote`,null,[n(`p`,null,`（拿着一盘看起来像是脆米的东西）我知道，在这里！！（把盘子递给她。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`450.648`,duration:`6.744`}),c[453]||=a(),c[454]||=n(`strong`,null,`Monica Geller:`,-1),c[455]||=a(` Ohhh! (Takes the plate.) No! This is my friend Rachel, we went to High School together.`,-1),c[456]||=n(`blockquote`,null,[n(`p`,null,`哦！（拿起盘子）不！这是我的朋友瑞秋，我们一起上的高中。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`457.392`,duration:`1.392`}),c[457]||=a(),c[458]||=n(`strong`,null,`Rachel Green:`,-1),c[459]||=a(` (giggles and can’t look at him) Hi!`,-1),c[460]||=n(`blockquote`,null,[n(`p`,null,`（咯咯笑着，不敢看他）嗨！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`458.784`,duration:`1.488`}),c[461]||=a(),c[462]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[463]||=a(` (shaking Rachel’s hand) Hi!`,-1),c[464]||=n(`blockquote`,null,[n(`p`,null,`（和瑞秋握手）嗨！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`460.272`,duration:`11.136`}),c[465]||=a(),c[466]||=n(`strong`,null,`Rachel Green:`,-1),c[467]||=a(` (still not quite able to look at him) Hi! I love you on that show! I watch you everyday! I mean, when you took out your own kidney to save your ex-wife even though she tired to kill you…`,-1),c[468]||=n(`blockquote`,null,[n(`p`,null,`（还是不能看着他）嗨！在那个节目里我爱你！我每天都看着你！我的意思是，当你取出自己的肾脏去救你的前妻，尽管她很想杀了你…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`471.408`,duration:`3.264`}),c[469]||=a(),c[470]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[471]||=a(` Well, it’s always nice to meet the fans.`,-1),c[472]||=n(`blockquote`,null,[n(`p`,null,`嗯，见到球迷总是很高兴。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`474.672`,duration:`1.296`}),c[473]||=a(),c[474]||=n(`strong`,null,`Rachel Green:`,-1),c[475]||=a(` Ah!`,-1),c[476]||=n(`blockquote`,null,[n(`p`,null,`啊！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`475.968`,duration:`2.376`}),c[477]||=a(),c[478]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[479]||=a(` (turning and whispering to Monica) She’s not crazy is she?`,-1),c[480]||=n(`blockquote`,null,[n(`p`,null,`（转身对莫妮卡耳语）她没疯吧？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`478.344`,duration:`1.512`}),c[481]||=a(),c[482]||=n(`strong`,null,`Monica Geller:`,-1),c[483]||=a(` No.`,-1),c[484]||=n(`blockquote`,null,[n(`p`,null,`没有。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`479.856`,duration:`2.424`}),c[485]||=a(),c[486]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[487]||=a(` (To Rachel) So uh, how you doin’?`,-1),c[488]||=n(`blockquote`,null,[n(`p`,null,`（对瑞秋）那你怎么样？`)],-1),c[489]||=n(`hr`,null,null,-1),c[490]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Phoebe's, Monica, Chandler, and Phoebe are there. Phoebe’s cell phone rings and she goes through her little routine of lighting a cigarette before answering the phone.`)],-1),c[491]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和菲比的、莫妮卡、钱德勒和菲比在那里。菲比的手机响了，她在接电话前按惯例点烟。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`482.28`,duration:`17.016`}),c[492]||=a(),c[493]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[494]||=a(` Hang on! Hang on! Hang on! (Answering the phone.) Go!! Who’s this? (Listens) Oh okay, you’re gonna like working for me. What’s your name? (Listens) What kind of name is Brendy? I… Whatever… Stop talking! All right, from now on your name is Joan. You can pick your own last name.`,-1),c[495]||=n(`blockquote`,null,[n(`p`,null,`等等！坚持坚持（接电话）走！！这是谁？（听）哦，好吧，你会喜欢为我工作的。你叫什么名字？（听）布兰迪叫什么名字？我…不管怎样…别说了！好的，从现在起你的名字是琼。你可以选择自己的姓。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`499.296`,duration:`1.944`}),c[496]||=a(),c[497]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[498]||=a(` (entering) Hey there you are!`,-1),c[499]||=n(`blockquote`,null,[n(`p`,null,`（进来）嘿，你在这儿！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`501.24`,duration:`2.64`}),c[500]||=a(),c[501]||=n(`strong`,null,`Chandler Bing:`,-1),c[502]||=a(` Uh-oh, it’s my boss!`,-1),c[503]||=n(`blockquote`,null,[n(`p`,null,`哦，是我老板！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`503.88`,duration:`13.728`}),c[504]||=a(),c[505]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[506]||=a(` All right, here’s a list of things for you to do today. Man, this going to be so great! Thank you so much! All right, I got to go to work I’m delivering twins today, but only one of them is mine! (Exits.)`,-1),c[507]||=n(`blockquote`,null,[n(`p`,null,`好吧，这是你今天要做的事情清单。老兄，这太棒了！非常感谢你！好吧，我得去上班了我今天要接生双胞胎，但其中只有一个是我的！（退出。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`517.608`,duration:`9.864`}),c[508]||=a(),c[509]||=n(`strong`,null,`Chandler Bing:`,-1),c[510]||=a(` (reading the list) Drop off my dry cleaning. Pick up my vitamins. Teach me how to spell vitamins. Wear in my new jeans.`,-1),c[511]||=n(`blockquote`,null,[n(`p`,null,`（读清单）把我干洗的衣服放下。吃我的维生素。教我如何拼写维生素。穿上我的新牛仔裤。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`527.472`,duration:`2.568`}),c[512]||=a(),c[513]||=n(`strong`,null,`Monica Geller:`,-1),c[514]||=a(` (laughs) You realize what you are don’t you?`,-1),c[515]||=n(`blockquote`,null,[n(`p`,null,`（笑）你知道你是什么，不是吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`530.04`,duration:`1.464`}),c[516]||=a(),c[517]||=n(`strong`,null,`Chandler Bing:`,-1),c[518]||=a(` What?`,-1),c[519]||=n(`blockquote`,null,[n(`p`,null,`什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`531.504`,duration:`1.944`}),c[520]||=a(),c[521]||=n(`strong`,null,`Monica Geller:`,-1),c[522]||=a(` You’re his bitch.`,-1),c[523]||=n(`blockquote`,null,[n(`p`,null,`你是他的婊子。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`533.448`,duration:`1.872`}),c[524]||=a(),c[525]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[526]||=a(` (yelling from Monica’s room) No-no!! No!!`,-1),c[527]||=n(`blockquote`,null,[n(`p`,null,`（从莫妮卡的房间里大叫）不不！！不`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`535.32`,duration:`4.704`}),c[528]||=a(),c[529]||=n(`strong`,null,`Monica Geller:`,-1),c[530]||=a(` (panicked) Oh wait! You didn’t just sit on my Kit-Kats did you?!!`,-1),c[531]||=n(`blockquote`,null,[n(`p`,null,`（惊慌失措）哦，等等！你不只是坐在我的装备上，是吗？！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`540.024`,duration:`5.16`}),c[532]||=a(),c[533]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[534]||=a(` No! There-there was a little, a little diff in the market and I lost 13 million dollars.`,-1),c[535]||=n(`blockquote`,null,[n(`p`,null,`不！市场上有点，有点差异，我损失了1300万美元。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`545.184`,duration:`2.544`}),c[536]||=a(),c[537]||=n(`strong`,null,`Chandler Bing:`,-1),c[538]||=a(` But the Kit-Kats are all right?!`,-1),c[539]||=n(`blockquote`,null,[n(`p`,null,`但是Kit Kat没事吧？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`547.728`,duration:`10.032`}),c[540]||=a(),c[541]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[542]||=a(` What am I gonna do?! What am I gonna do?! I can’t call my office they’ll kill me! I can’t call my clients they’ll kill themselves! Great, now my chest hearts.`,-1),c[543]||=n(`blockquote`,null,[n(`p`,null,`我该怎么办？！我该怎么办？！我不能给我的办公室打电话他们会杀了我的！我不能给我的客户打电话他们会自杀的！太好了，现在我的胸脯发自肺腑。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`557.76`,duration:`1.464`}),c[544]||=a(),c[545]||=n(`strong`,null,`Monica Geller:`,-1),c[546]||=a(` What?!`,-1),c[547]||=n(`blockquote`,null,[n(`p`,null,`什么？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`559.224`,duration:`3.168`}),c[548]||=a(),c[549]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[550]||=a(` (louder) My chest hurts! Oh, and now I-I can’t breathe.`,-1),c[551]||=n(`blockquote`,null,[n(`p`,null,`（大声一点）我的胸口疼！哦，现在我不能呼吸了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`562.392`,duration:`3.216`}),c[552]||=a(),c[553]||=n(`strong`,null,`Chandler Bing:`,-1),c[554]||=a(` Phoebe, are you having a heart attack?!`,-1),c[555]||=n(`blockquote`,null,[n(`p`,null,`菲比，你心脏病发作了吗？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`565.608`,duration:`3.888`}),c[556]||=a(),c[557]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[558]||=a(` Oh, if I were, would-would I have shooting pains up and down my left arm?`,-1),c[559]||=n(`blockquote`,null,[n(`p`,null,`哦，如果是的话，我会不会左臂上下都有阵痛？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`569.496`,duration:`1.608`}),c[560]||=a(),c[561]||=n(`strong`,null,`Monica Geller:`,-1),c[562]||=a(` Yes!!`,-1),c[563]||=n(`blockquote`,null,[n(`p`,null,`是的！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`571.104`,duration:`2.136`}),c[564]||=a(),c[565]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[566]||=a(` Then yes that is what I’m having. (Takes another puff of the cigarette.)`,-1),c[567]||=n(`blockquote`,null,[n(`p`,null,`那是的，这就是我要吃的。（又吸了一口烟。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`573.24`,duration:`1.8`}),c[568]||=o(` <strong>Monica Geller:</strong> Oh my God!<blockquote><p>哦，我的天啊！</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>A hospital, Phoebe is recovering from her heart attack as Ross, Monica, and Chandler are there to comfort and support her.</em></p><blockquote><p>🎬 <em>一家医院，菲比正在从心脏病发作中恢复，罗斯、莫妮卡和钱德勒在那里安慰和支持她。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`575.04`,duration:`8.136`}),c[569]||=a(),c[570]||=n(`strong`,null,`Ross Geller:`,-1),c[571]||=a(` Come on Pheebs, it’s not that bad! Y’know most people would be excited if they didn’t have to work for a couple of weeks.`,-1),c[572]||=n(`blockquote`,null,[n(`p`,null,`来吧，菲比，没那么糟！你知道大多数人都会很兴奋，如果他们不需要工作几个星期的话。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`583.176`,duration:`8.016`}),c[573]||=a(),c[574]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[575]||=a(` Most people don’t like their jobs, I love my job! I have not been working for three hours and I’m already going crazy. I miss Joan.`,-1),c[576]||=n(`blockquote`,null,[n(`p`,null,`大多数人不喜欢他们的工作，我爱我的工作！我已经三个小时没工作了，我已经疯了。我想念琼。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`591.192`,duration:`5.016`}),c[577]||=a(),c[578]||=n(`strong`,null,`Monica Geller:`,-1),c[579]||=a(` Honey, having a heart attack is nature’s way of telling you to slow it down.`,-1),c[580]||=n(`blockquote`,null,[n(`p`,null,`亲爱的，心脏病发作是大自然告诉你要慢下来的方式。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`596.208`,duration:`13.128`}),c[581]||=a(),c[582]||=n(`strong`,null,`Chandler Bing:`,-1),c[583]||=a(` I always thought having a heart attack was nature’s way of telling you to die! (Phoebe glares at him.) But you’re not gonna die. I mean, you are going to die, but you’re not gonna die today. I wish I was dead.`,-1),c[584]||=n(`blockquote`,null,[n(`p`,null,`我一直认为心脏病发作是大自然告诉你去死的方式！（菲比瞪着他）但你不会死的。我是说，你会死，但你今天不会死。我希望我死了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`609.336`,duration:`6.72`}),c[585]||=a(),c[586]||=n(`strong`,null,`Monica Geller:`,-1),c[587]||=a(` Let’s take a walk. (They start to leave.) Y’know maybe you should consider writing for Talking Out of Your Ass magazine! (They exit.)`,-1),c[588]||=n(`blockquote`,null,[n(`p`,null,`我们去散散步吧。（他们开始离开了）你也许应该考虑写一本你的屁股杂志。（他们离开了。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`616.056`,duration:`1.848`}),c[589]||=a(),c[590]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[591]||=a(` (To Ross) So what’s going on with you?`,-1),c[592]||=n(`blockquote`,null,[n(`p`,null,`（对罗斯）你怎么了？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`617.904`,duration:`3.816`}),c[593]||=a(),c[594]||=n(`strong`,null,`Ross Geller:`,-1),c[595]||=a(` Well umm, I’ve been doing a lot more of my kara-tay.`,-1),c[596]||=n(`blockquote`,null,[n(`p`,null,`嗯，我的卡拉·泰已经做了很多了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`621.72`,duration:`2.712`}),c[597]||=a(),c[598]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[599]||=a(` Still going through that dry spell with Carol?`,-1),c[600]||=n(`blockquote`,null,[n(`p`,null,`还和卡萝一起经历旱季吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`624.432`,duration:`1.368`}),c[601]||=a(),c[602]||=n(`strong`,null,`Ross Geller:`,-1),c[603]||=a(` Yeah.`,-1),c[604]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`625.8`,duration:`2.592`}),c[605]||=a(),c[606]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[607]||=a(` How long has it been since you had sex?`,-1),c[608]||=n(`blockquote`,null,[n(`p`,null,`你有多久没做爱了？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`628.392`,duration:`2.424`}),c[609]||=a(),c[610]||=n(`strong`,null,`Ross Geller:`,-1),c[611]||=a(` Well, last weekend…`,-1),c[612]||=n(`blockquote`,null,[n(`p`,null,`嗯，上周末…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`630.816`,duration:`1.656`}),c[613]||=a(),c[614]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[615]||=a(` Oh that’s not so bad.`,-1),c[616]||=n(`blockquote`,null,[n(`p`,null,`哦，没那么糟。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`632.472`,duration:`2.136`}),c[617]||=a(),c[618]||=n(`strong`,null,`Ross Geller:`,-1),c[619]||=a(` …will be two months…`,-1),c[620]||=n(`blockquote`,null,[n(`p`,null,`……将是两个月…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`634.608`,duration:`1.056`}),c[621]||=a(),c[622]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[623]||=a(` That is.`,-1),c[624]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`635.664`,duration:`2.376`}),c[625]||=a(),c[626]||=n(`strong`,null,`Ross Geller:`,-1),c[627]||=a(` …since I stopped trying.`,-1),c[628]||=n(`blockquote`,null,[n(`p`,null,`……自从我停止尝试以来。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`638.04`,duration:`2.4`}),c[629]||=a(),c[630]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[631]||=a(` Maybe you need to spice things up a little.`,-1),c[632]||=n(`blockquote`,null,[n(`p`,null,`也许你需要让事情变得有趣一点。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`640.44`,duration:`1.944`}),c[633]||=a(),c[634]||=n(`strong`,null,`Ross Geller:`,-1),c[635]||=a(` What-what do you mean?`,-1),c[636]||=n(`blockquote`,null,[n(`p`,null,`什么意思？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`642.384`,duration:`4.944`}),c[637]||=a(),c[638]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[639]||=a(` I don’t know. You could tie her up, she could tie you up; you could eat stuff off each other…`,-1),c[640]||=n(`blockquote`,null,[n(`p`,null,`我不知道。你可以把她绑起来，她可以把你绑起来；你们可以互相吃东西…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`647.328`,duration:`1.368`}),c[641]||=a(),c[642]||=n(`strong`,null,`Ross Geller:`,-1),c[643]||=a(` Oh.`,-1),c[644]||=n(`blockquote`,null,[n(`p`,null,`哦。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`648.696`,duration:`2.496`}),c[645]||=a(),c[646]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[647]||=a(` Y’know, dirty talk, m�nage � trois, toys…`,-1),c[648]||=n(`blockquote`,null,[n(`p`,null,`你知道，脏话，m�纳格� 特洛伊，玩具…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`651.192`,duration:`1.488`}),c[649]||=a(),c[650]||=n(`strong`,null,`Ross Geller:`,-1),c[651]||=a(` Wow!`,-1),c[652]||=n(`blockquote`,null,[n(`p`,null,`哇！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`652.68`,duration:`7.344`}),c[653]||=a(),c[654]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[655]||=a(` Roll playing… You could be the warden; she could be the prisoner. You could be the pirate; she could be the wench!`,-1),c[656]||=n(`blockquote`,null,[n(`p`,null,`滚吧……你可能是监狱长；她可能就是那个囚犯。你可能是海盗；她可能就是那个婊子！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`660.024`,duration:`2.568`}),c[657]||=a(),c[658]||=n(`strong`,null,`Ross Geller:`,-1),c[659]||=a(` Okay, I think I got it.`,-1),c[660]||=n(`blockquote`,null,[n(`p`,null,`好的，我想我明白了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`662.592`,duration:`8.136`}),c[661]||=a(),c[662]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[663]||=a(` Yeah! Or too, you could be two stockbrokers and you’re-you’re-you’re rolling around naked on the trading floor and everybody’s watching! (Ross looks at her.) It never happened.`,-1),c[664]||=n(`blockquote`,null,[n(`p`,null,`是啊！或者，你也可以是两个股票经纪人，你，你，你，你在交易大厅里裸体翻滚，每个人都在看着！（罗斯看着她）这从来没有发生过。`)],-1),c[665]||=n(`hr`,null,null,-1),c[666]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`A hospital hallway, Chandler is sitting on a gurney with his hands spread out behind his back. Then Monica comes and plops down on the gurney and one of his hands. Chandler immediately recoils in extreme pain.`)],-1),c[667]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`医院走廊，钱德勒坐在轮床上，双手摊开放在背后。然后莫妮卡过来扑通一声倒在轮床上和他的一只手上。钱德勒立即因极度疼痛而后退。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`670.728`,duration:`4.056`}),c[668]||=a(),c[669]||=n(`strong`,null,`Monica Geller:`,-1),c[670]||=a(` Sorry. So how’s it going with Joey?`,-1),c[671]||=n(`blockquote`,null,[n(`p`,null,`对不起。乔伊怎么样了？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`674.784`,duration:`14.904`}),c[672]||=a(),c[673]||=n(`strong`,null,`Chandler Bing:`,-1),c[674]||=a(` Oh just great. He beeps me now with codes. One is, "Bring me food." Two is, "I’m with a girl, bring us food." Three is, "I’m lost and I can’t find food."`,-1),c[675]||=n(`blockquote`,null,[n(`p`,null,`哦，太好了。他现在用密码给我打呼机。一个是“给我带食物。”二个是“我和一个女孩在一起，给我们带食物。”三个是“我迷路了，我找不到食物。”`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`689.688`,duration:`4.392`}),c[676]||=a(),c[677]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[678]||=a(` (entering) Hey! Is uh, is she gonna be all right?`,-1),c[679]||=n(`blockquote`,null,[n(`p`,null,`（进来）嘿！她没事吧？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`694.08`,duration:`3.456`}),c[680]||=a(),c[681]||=n(`strong`,null,`Monica Geller:`,-1),c[682]||=a(` Yeah! She’s right in there! (Points to Phoebe’s room.)`,-1),c[683]||=n(`blockquote`,null,[n(`p`,null,`是啊！她就在那里！（指向菲比的房间。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`697.536`,duration:`6.192`}),c[684]||=a(),c[685]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[686]||=a(` Oh great. (Starts to go in.) (To Chandler) Hey! Go take off those pants, they look ready!`,-1),c[687]||=n(`blockquote`,null,[n(`p`,null,`哦，太好了。（开始进去。）（对钱德勒）嘿！去把裤子脱下来，它们看起来准备好了！`)],-1),c[688]||=n(`hr`,null,null,-1),c[689]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Silvercup Studios, Joey is showing Rachel around the set.`)],-1),c[690]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`银杯影城，乔伊带瑞秋参观片场。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`703.728`,duration:`5.568`}),c[691]||=a(),c[692]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[693]||=a(` All right, and over there is Brady’s Pub where I like to unwind after a long day of surgeoning.`,-1),c[694]||=n(`blockquote`,null,[n(`p`,null,`好吧，那边是布雷迪酒吧，我在那里做了一整天的手术后，喜欢放松一下。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`709.296`,duration:`6.576`}),c[695]||=a(),c[696]||=n(`strong`,null,`Rachel Green:`,-1),c[697]||=a(` Wow! This is so amazing! What else? What else?`,-1),c[698]||=n(`blockquote`,null,[n(`p`,null,`哇！这太神奇了！还有什么？还有什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`715.872`,duration:`7.992`}),c[699]||=a(),c[700]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[701]||=a(` Well, that is a large piece of television equipment. (Points at a large piece of television equipment as an old man walks by.) And uh that is an old man! Hey old man!`,-1),c[702]||=n(`blockquote`,null,[n(`p`,null,`嗯，那是一个很大的电视设备。（一位老人走过时指着一大块电视设备。）嗯，那是一位老人！嘿，老家伙！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`723.864`,duration:`1.392`}),c[703]||=a(),c[704]||=n(`strong`,null,`Rachel Green:`,-1),c[705]||=a(` Hey!`,-1),c[706]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`725.256`,duration:`3.648`}),c[707]||=a(),c[708]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[709]||=a(` All righty, what do you say we head back to my place?`,-1),c[710]||=n(`blockquote`,null,[n(`p`,null,`好吧，我们回我家怎么样？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`728.904`,duration:`5.784`}),c[711]||=a(),c[712]||=n(`strong`,null,`Rachel Green:`,-1),c[713]||=a(` (laughs) Wow! Umm, y’know, I-I would really love to, but I-I shouldn’t.`,-1),c[714]||=n(`blockquote`,null,[n(`p`,null,`（笑）哇！嗯，你知道，我真的很想去，但我不应该去。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`734.688`,duration:`6.768`}),c[715]||=a(),c[716]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[717]||=a(` Why? (In Drake’s voice.) Why can’t the world stop turning, just for a moment? Just for us?`,-1),c[718]||=n(`blockquote`,null,[n(`p`,null,`为什么？（用德雷克的声音）为什么世界不能停止转动，就一会儿？就为了我们？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`741.456`,duration:`2.448`}),c[719]||=a(),c[720]||=n(`strong`,null,`Rachel Green:`,-1),c[721]||=a(` (awestruck, then not) Isn’t that a line from the show?!`,-1),c[722]||=n(`blockquote`,null,[n(`p`,null,`（敬畏，那么不是）这不是节目里的台词吗？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`743.904`,duration:`7.08`}),c[723]||=a(),c[724]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[725]||=a(` Uh, yeah but uh, (In Drake’s voice) I may have said those things before but, I never truly meant them. Until now.`,-1),c[726]||=n(`blockquote`,null,[n(`p`,null,`嗯，是的，但是，（用德雷克的声音）我以前可能说过这些话，但是，我从来没有真正说过。直到现在。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`750.984`,duration:`2.568`}),c[727]||=a(),c[728]||=n(`strong`,null,`Rachel Green:`,-1),c[729]||=a(` That’s a line from the show too!`,-1),c[730]||=n(`blockquote`,null,[n(`p`,null,`那也是节目里的台词！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`753.552`,duration:`2.952`}),c[731]||=a(),c[732]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[733]||=a(` Okay, you watch too much TV.`,-1),c[734]||=n(`blockquote`,null,[n(`p`,null,`好吧，你看电视太多了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`756.504`,duration:`5.016`}),c[735]||=a(),c[736]||=n(`strong`,null,`Chandler Bing:`,-1),c[737]||=a(` (approaching) Here you go Joe, here’s the freshly squeezed orange juice you asked for. (Hands it to him.)`,-1),c[738]||=n(`blockquote`,null,[n(`p`,null,`（走近）给你乔，这是你要的鲜榨橙汁。（递给他。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`761.52`,duration:`3.984`}),c[739]||=a(),c[740]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[741]||=a(` Thanks! (Looks at it.) Yeah, there’s pulp in that. (Hands it back.)`,-1),c[742]||=n(`blockquote`,null,[n(`p`,null,`谢谢！（看着它）是的，里面有果肉。（把它还给我。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`765.504`,duration:`1.392`}),c[743]||=a(),c[744]||=n(`strong`,null,`Chandler Bing:`,-1),c[745]||=a(` Yeah?`,-1),c[746]||=n(`blockquote`,null,[n(`p`,null,`是吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`766.896`,duration:`10.368`}),c[747]||=a(),c[748]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[749]||=a(` I thought we talked about this. I don’t like pulp. No pulp. Pulp isn’t juice. All juice, okay?`,-1),c[750]||=n(`blockquote`,null,[n(`p`,null,`我以为我们已经谈过了。我不喜欢果肉。没有果肉。果肉不是果汁。全是果汁，好吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`777.264`,duration:`3.384`}),c[751]||=a(),c[752]||=n(`strong`,null,`Chandler Bing:`,-1),c[753]||=a(` I’m sorry, I guess I just like the pulp.`,-1),c[754]||=n(`blockquote`,null,[n(`p`,null,`对不起，我想我只是喜欢果肉。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`780.648`,duration:`9.624`}),c[755]||=a(),c[756]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[757]||=a(` Oh my God, I’m sorry, I’m being so rude. (Turns to Rachel.) Rachel, would like a soda or something? Because Chandler would run right out and get it.`,-1),c[758]||=n(`blockquote`,null,[n(`p`,null,`我的天啊，对不起，我太粗鲁了。（转向瑞秋）瑞秋，要不要来杯苏打水什么的？因为钱德勒会马上跑出去拿。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`790.272`,duration:`3.048`}),c[759]||=a(),c[760]||=n(`strong`,null,`Rachel Green:`,-1),c[761]||=a(` Yeah sure, iced tea would be great.`,-1),c[762]||=n(`blockquote`,null,[n(`p`,null,`当然，冰茶会很棒的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`793.32`,duration:`1.848`}),c[763]||=a(),c[764]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[765]||=a(` (To Chandler) Iced tea.`,-1),c[766]||=n(`blockquote`,null,[n(`p`,null,`（对钱德勒）冰茶。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`795.168`,duration:`2.736`}),c[767]||=a(),c[768]||=n(`strong`,null,`Chandler Bing:`,-1),c[769]||=a(` Okay, anything for you sir?`,-1),c[770]||=n(`blockquote`,null,[n(`p`,null,`好的，先生，有什么事吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`797.904`,duration:`2.16`}),c[771]||=a(),c[772]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[773]||=a(` (To Rachel) Did I not just tell him?`,-1),c[774]||=n(`blockquote`,null,[n(`p`,null,`（对瑞秋）我不是刚告诉他了吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`800.064`,duration:`2.184`}),c[775]||=a(),c[776]||=n(`strong`,null,`Rachel Green:`,-1),c[777]||=a(` (mouthing it to him) Yes, you did.`,-1),c[778]||=n(`blockquote`,null,[n(`p`,null,`（对他说）是的，你说了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`802.248`,duration:`6.768`}),c[779]||=a(),c[780]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[781]||=a(` (To Chandler) Okay look, Chandler, if this (Motions back and forth indicating the arrangement.) you have got to listen! (Tugs on his ear.) (Chandler glares at him.) You’re gonna throw that juice at me, aren’t ya?`,-1),c[782]||=n(`blockquote`,null,[n(`p`,null,`（对钱德勒）好的，听着，钱德勒，如果这个（来回的动作表明安排）你必须听！（拉了拉他的耳朵。）（钱德勒瞪了他一眼。）你要把果汁扔给我，是吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`809.016`,duration:`2.28`}),c[783]||=a(),c[784]||=n(`strong`,null,`Chandler Bing:`,-1),c[785]||=a(` It’s not all juice! (Rachel quickly gets out of the way.)`,-1),c[786]||=n(`blockquote`,null,[n(`p`,null,`不全是果汁！（瑞秋很快就闪开了。）`)],-1),c[787]||=n(`hr`,null,null,-1),c[788]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Ross and Carol's, Ross is trying to talk to Carol about what Phoebe told him.`)],-1),c[789]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`罗斯和卡萝家，罗斯正试图和卡萝谈谈菲比告诉他的事。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`811.296`,duration:`6.312`}),c[790]||=a(),c[791]||=n(`strong`,null,`Ross Geller:`,-1),c[792]||=a(` So honey, this morning was fun, huh? Me hopping in on you in the shower there.`,-1),c[793]||=n(`blockquote`,null,[n(`p`,null,`亲爱的，今天早上很有趣，是吗？我在那里洗澡的时候看到你了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`817.608`,duration:`4.344`}),c[794]||=a(),c[795]||=n(`strong`,null,`Carol Willick:`,-1),c[796]||=a(` Yeah! And maybe someday we could get a place with two bathrooms.`,-1),c[797]||=n(`blockquote`,null,[n(`p`,null,`是啊！也许有一天我们能找到一个有两个浴室的地方。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`821.952`,duration:`6.264`}),c[798]||=a(),c[799]||=n(`strong`,null,`Ross Geller:`,-1),c[800]||=a(` Look Carol umm, I was, I was thinking maybe uh, maybe we can spice things up a little.`,-1),c[801]||=n(`blockquote`,null,[n(`p`,null,`听着，卡萝，嗯，我是，我在想也许，也许我们可以让事情变得有趣一点。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`828.216`,duration:`1.176`}),c[802]||=a(),c[803]||=n(`strong`,null,`Carol Willick:`,-1),c[804]||=a(` What do you mean?`,-1),c[805]||=n(`blockquote`,null,[n(`p`,null,`你什么意思？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`829.392`,duration:`3.984`}),c[806]||=a(),c[807]||=n(`strong`,null,`Ross Geller:`,-1),c[808]||=a(` Carol our sex life is—it’s just not working…`,-1),c[809]||=n(`blockquote`,null,[n(`p`,null,`卡萝，我们的性生活就是不正常…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`833.376`,duration:`0.744`}),c[810]||=a(),c[811]||=n(`strong`,null,`Ben:`,-1),c[812]||=a(` (entering) Dad!! (Runs and hugs him.)`,-1),c[813]||=n(`blockquote`,null,[n(`p`,null,`（进来）爸爸！！（跑过去拥抱他。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`834.12`,duration:`12.864`}),c[814]||=a(),c[815]||=n(`strong`,null,`Ross Geller:`,-1),c[816]||=a(` Hey there little fella! Hey, uh-hey, why don’t we get some shoes on ya, huh? Hey, why don’t you show dad how you can put your shoes on, in your room! Yay!!`,-1),c[817]||=n(`blockquote`,null,[n(`p`,null,`嘿，小家伙！嘿，呃，嘿，我们为什么不给你穿双鞋呢？嘿，你为什么不在你的房间里告诉爸爸你怎么穿鞋子呢！耶！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`846.984`,duration:`0.768`}),c[818]||=a(),c[819]||=n(`strong`,null,`Ben:`,-1),c[820]||=a(` Yay! (Runs off.)`,-1),c[821]||=n(`blockquote`,null,[n(`p`,null,`耶！（跑掉了。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`847.752`,duration:`12.192`}),c[822]||=a(),c[823]||=n(`strong`,null,`Ross Geller:`,-1),c[824]||=a(` Yay! (To Carol) Seriously, our sex life… I was thinking, maybe I don’t know, we could try some-some new things. Y’know? For fun?`,-1),c[825]||=n(`blockquote`,null,[n(`p`,null,`耶！（对卡萝）说真的，我们的性生活……我在想，也许我不知道，我们可以尝试一些新东西。你知道吗？为了好玩？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`859.944`,duration:`1.248`}),c[826]||=a(),c[827]||=n(`strong`,null,`Carol Willick:`,-1),c[828]||=a(` Like what?`,-1),c[829]||=n(`blockquote`,null,[n(`p`,null,`像什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`861.192`,duration:`15.24`}),c[830]||=a(),c[831]||=n(`strong`,null,`Ross Geller:`,-1),c[832]||=a(` Well I don’t know umm, (Pause) what if we were too tie each other up? (Carol’s shocked and obviously doesn’t like that idea.) Umm, some people eat stuff off one another. (Carol doesn’t like that idea either.) Nah! Umm, y’know we-we could try dirty talk? (Carol still says no.) Umm, we could, we could have a threesome.`,-1),c[833]||=n(`blockquote`,null,[n(`p`,null,`我不知道，嗯，（停顿）如果我们太拘束了怎么办？（卡萝很震惊，显然不喜欢这个主意。）嗯，有些人互相吃东西。（卡萝也不喜欢这个主意。）不！嗯，你知道我们可以尝试下流话吗？（卡萝仍然拒绝）嗯，我们可以，我们可以三人行。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`876.432`,duration:`1.68`}),c[834]||=a(),c[835]||=n(`strong`,null,`Carol Willick:`,-1),c[836]||=a(` (quickly) I love that idea!`,-1),c[837]||=n(`blockquote`,null,[n(`p`,null,`（很快）我喜欢这个主意！`)],-1),c[838]||=n(`hr`,null,null,-1),c[839]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Phoebe's, Monica is eating breakfast as Chandler enters.`)],-1),c[840]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和菲比家，钱德勒进来时莫妮卡正在吃早餐。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`878.112`,duration:`3.24`}),c[841]||=a(),c[842]||=n(`strong`,null,`Chandler Bing:`,-1),c[843]||=a(` Who sold a story to Archie Comics?!`,-1),c[844]||=n(`blockquote`,null,[n(`p`,null,`谁把故事卖给了阿尔奇漫画？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`881.352`,duration:`9.72`}),c[845]||=a(),c[846]||=n(`strong`,null,`Monica Geller:`,-1),c[847]||=a(` Oh my God! That’s great! Oh wow! (Hugs him.) You’re a published writer! I wish I had a present for you!`,-1),c[848]||=n(`blockquote`,null,[n(`p`,null,`哦，我的天啊！太好了！哦，哇！（拥抱他）你是一个出版作家！我希望我有一件礼物给你！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`891.072`,duration:`1.368`}),c[849]||=a(),c[850]||=n(`strong`,null,`Chandler Bing:`,-1),c[851]||=a(` Aww.`,-1),c[852]||=n(`blockquote`,null,[n(`p`,null,`啊。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`892.44`,duration:`4.248`}),c[853]||=a(),c[854]||=n(`strong`,null,`Monica Geller:`,-1),c[855]||=a(` Wait a minute! (Quickly checks her pockets and pulls out…) My last Kit-Kat bar!`,-1),c[856]||=n(`blockquote`,null,[n(`p`,null,`等一下！（迅速检查她的口袋并拿出…）我的最后一个Kit Kat酒吧！`)],-1),c[857]||=n(`p`,null,[n(`em`,null,`(Chandler tries to take it, but Monica won’t let go. He tugs harder, and she still doesn’t budge.)`)],-1),c[858]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（钱德勒试图抓住它，但莫妮卡不肯放手。他用力拉，她还是一动不动。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`896.688`,duration:`1.92`}),c[859]||=a(),c[860]||=n(`strong`,null,`Chandler Bing:`,-1),c[861]||=a(` You wanna share it?`,-1),c[862]||=n(`blockquote`,null,[n(`p`,null,`你想和我分享吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`898.608`,duration:`1.56`}),c[863]||=a(),c[864]||=n(`strong`,null,`Monica Geller:`,-1),c[865]||=a(` Okay!!`,-1),c[866]||=n(`blockquote`,null,[n(`p`,null,`好的！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`900.168`,duration:`18.888`}),c[867]||=a(),c[868]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[869]||=a(` (entering) Hey! Hey Chandler look, I know you’re mad, but I just want to say I’m sorry. I-I was a total jerk. Completely o-over the line. Uh, I just I hate pulp! Y’know? I mean, y’know how Monica feels about low fat mayonnaise?`,-1),c[870]||=n(`blockquote`,null,[n(`p`,null,`（进来）嘿！嘿，钱德勒，听着，我知道你很生气，但我只是想说声对不起。我是个十足的混蛋。完全越过了线。呃，我只是我讨厌果肉！你知道吗？我是说，你知道莫妮卡对低脂蛋黄酱的感觉吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`919.056`,duration:`2.232`}),c[871]||=a(),c[872]||=n(`strong`,null,`Monica Geller:`,-1),c[873]||=a(` It’s not mayonnaise!!`,-1),c[874]||=n(`blockquote`,null,[n(`p`,null,`这不是蛋黄酱！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`921.288`,duration:`5.544`}),c[875]||=a(),c[876]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[877]||=a(` Yeah, o-o-o-o-okay anyway, I just wanted to say I’m sorry. Here. (Hands him a cup.)`,-1),c[878]||=n(`blockquote`,null,[n(`p`,null,`是啊，好吧，我只是想说声对不起。在这里（递给他一杯。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`926.832`,duration:`1.752`}),c[879]||=a(),c[880]||=n(`strong`,null,`Chandler Bing:`,-1),c[881]||=a(` What’s this?`,-1),c[882]||=n(`blockquote`,null,[n(`p`,null,`这是什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`928.584`,duration:`5.376`}),c[883]||=a(),c[884]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[885]||=a(` Fresh squeezed orange juice, with pulp! Just the way you like it.`,-1),c[886]||=n(`blockquote`,null,[n(`p`,null,`鲜榨橙汁，加果肉！就像你喜欢的那样。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`933.96`,duration:`2.304`}),c[887]||=a(),c[888]||=n(`strong`,null,`Chandler Bing:`,-1),c[889]||=a(` Aww, thanks man. (They hug.)`,-1),c[890]||=n(`blockquote`,null,[n(`p`,null,`哦，谢谢你，伙计。（他们拥抱。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`936.264`,duration:`4.224`}),c[891]||=a(),c[892]||=n(`strong`,null,`Monica Geller:`,-1),c[893]||=a(` Hey Joey, Chandler sold a story to Archie Comics!`,-1),c[894]||=n(`blockquote`,null,[n(`p`,null,`嘿，乔伊，钱德勒把故事卖给了阿尔奇漫画公司！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`940.488`,duration:`7.416`}),c[895]||=a(),c[896]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[897]||=a(` Oh my God! That’s great! Congratulations! What’s the story?!`,-1),c[898]||=n(`blockquote`,null,[n(`p`,null,`哦，我的天啊！太好了！祝贺怎么回事？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`947.904`,duration:`5.832`}),c[899]||=a(),c[900]||=n(`strong`,null,`Chandler Bing:`,-1),c[901]||=a(` Oh you wouldn’t uh, care. It’s just a stupid comic book story.`,-1),c[902]||=n(`blockquote`,null,[n(`p`,null,`哦，你不会在意的。这只是一个愚蠢的漫画故事。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`953.736`,duration:`5.832`}),c[903]||=a(),c[904]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[905]||=a(` Are you kidding me?! I love Archie! And the whole gang!`,-1),c[906]||=n(`blockquote`,null,[n(`p`,null,`你在开玩笑吗？！我爱阿奇！还有整个帮派！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`959.568`,duration:`16.752`}),c[907]||=a(),c[908]||=n(`strong`,null,`Chandler Bing:`,-1),c[909]||=a(` Well uh, Archie needs money to fix his jalopy (Joey laughs), uh but he doesn’t want Reggie to just give him the money. So Reggie hires him as his assist—as his butler. And then makes him do all these crazy things like bring him milkshakes that can’t have lumps in them.`,-1),c[910]||=n(`blockquote`,null,[n(`p`,null,`嗯，阿奇需要钱来修理他的老爷车（乔伊笑），但他不想雷吉把钱给他。所以雷吉雇佣他作为他的助手和管家。然后让他做所有这些疯狂的事情，比如给他带上不会结块的奶昔。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`976.32`,duration:`8.736`}),c[911]||=a(),c[912]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[913]||=a(` Wait a minute. That sounds a little familiar! Did they already do that one? ‘Cause I think I read it!`,-1),c[914]||=n(`blockquote`,null,[n(`p`,null,`等一下。听起来有点熟悉！他们已经这么做了吗？”因为我想我读过了！`)],-1),c[915]||=n(`hr`,null,null,-1),c[916]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Central Perk, Monica is there as Rachel enters.`)],-1),c[917]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`中央公园，瑞秋进来时莫妮卡在那里。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`985.056`,duration:`9.168`}),c[918]||=a(),c[919]||=n(`strong`,null,`Rachel Green:`,-1),c[920]||=a(` Oh Mon, listen I have to ask! Okay, Joey Tribbiani invited me back to his apartment, now does he do this with a lot of girls?`,-1),c[921]||=n(`blockquote`,null,[n(`p`,null,`哦，妈妈，听着，我得问问！好吧，乔伊·特里比亚尼邀请我回他的公寓，现在他会和很多女孩这样做吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`994.224`,duration:`4.152`}),c[922]||=a(),c[923]||=n(`strong`,null,`Monica Geller:`,-1),c[924]||=a(` Yeah, a lot. A lot, a lot!`,-1),c[925]||=n(`blockquote`,null,[n(`p`,null,`是的，很多。很多，很多！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`998.376`,duration:`9.744`}),c[926]||=a(),c[927]||=n(`strong`,null,`Rachel Green:`,-1),c[928]||=a(` Ohh! And I’m one of them!! Wow! Oh, I just cannot believe this! I mean, Joey Tribbiani!`,-1),c[929]||=n(`blockquote`,null,[n(`p`,null,`哦！我也是他们中的一员！！哇！哦，我简直不敢相信！我是说，乔伊·特里比亚尼！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1008.12`,duration:`4.08`}),c[930]||=a(),c[931]||=n(`strong`,null,`Monica Geller:`,-1),c[932]||=a(` Well, y’know it’s none of my business, but aren’t you married?`,-1),c[933]||=n(`blockquote`,null,[n(`p`,null,`嗯，你知道这不关我的事，但你不是结婚了吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1012.2`,duration:`8.088`}),c[934]||=a(),c[935]||=n(`strong`,null,`Rachel Green:`,-1),c[936]||=a(` Yeah. Oh I just wish we could not be married for a little bit! Y’know I just wish we could be like on a break!`,-1),c[937]||=n(`blockquote`,null,[n(`p`,null,`是的。哦，我只是希望我们不能结婚一点点！你知道我只是希望我们能像在休息！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1020.288`,duration:`2.088`}),c[938]||=a(),c[939]||=n(`strong`,null,`Monica Geller:`,-1),c[940]||=a(` Well, you’re not.`,-1),c[941]||=n(`blockquote`,null,[n(`p`,null,`嗯，你不是。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1022.376`,duration:`6.12`}),c[942]||=a(),c[943]||=n(`strong`,null,`Rachel Green:`,-1),c[944]||=a(` Oh, it’s so easy for you I mean, you’re not married, you get to have sex with who ever you want!`,-1),c[945]||=n(`blockquote`,null,[n(`p`,null,`哦，这对你来说太容易了，我是说，你还没结婚，你可以和任何你想要的人做爱！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1028.496`,duration:`7.824`}),c[946]||=a(),c[947]||=n(`strong`,null,`Monica Geller:`,-1),c[948]||=a(` Yeah I can! (Laughs) And don’t think I don’t, because I do! I mean all the time, you betcha! (Laughs.)`,-1),c[949]||=n(`blockquote`,null,[n(`p`,null,`是的，我能！（笑）别以为我没有，因为我有！我的意思是一直都是，没错！（笑）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1036.32`,duration:`4.032`}),c[950]||=a(),c[951]||=n(`strong`,null,`Rachel Green:`,-1),c[952]||=a(` Monica. You’ve, you’ve done it right?`,-1),c[953]||=n(`blockquote`,null,[n(`p`,null,`莫妮卡。你，你做得对吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1040.352`,duration:`5.376`}),c[954]||=a(),c[955]||=n(`strong`,null,`Monica Geller:`,-1),c[956]||=a(` (giggles) Of course I have! What do you think, I’m some 30 year old virgin?`,-1),c[957]||=n(`blockquote`,null,[n(`p`,null,`（咯咯笑）我当然有！你觉得我是个30岁的处女吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1045.728`,duration:`4.176`}),c[958]||=a(),c[959]||=n(`strong`,null,`Rachel Green:`,-1),c[960]||=a(` Oh my God! You’re a 30 year old virgin!`,-1),c[961]||=n(`blockquote`,null,[n(`p`,null,`我的天啊！你是个30岁的处女！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1049.904`,duration:`4.344`}),c[962]||=a(),c[963]||=n(`strong`,null,`Monica Geller:`,-1),c[964]||=a(` Say it louder, I don’t think the guy all the way in the back heard you!`,-1),c[965]||=n(`blockquote`,null,[n(`p`,null,`大声点说，我想后面的那个家伙没有听到你说的话！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1054.248`,duration:`1.08`}),c[966]||=a(),c[967]||=n(`strong`,null,`Guy All the Way in the Back:`,-1),c[968]||=a(` Yeah, I heard it.`,-1),c[969]||=n(`blockquote`,null,[n(`p`,null,`是的，我听到了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1055.328`,duration:`17.952`}),c[970]||=a(),c[971]||=n(`strong`,null,`Monica Geller:`,-1),c[972]||=a(` It’s not like, I haven’t any opportunities. I mean, y’know, I’m just waiting for the perfect guy. I’m seeing this guy Roger, all right? He’s not perfect, but umm, I think maybe I should just get it over with. Y’know, give him my flower.`,-1),c[973]||=n(`blockquote`,null,[n(`p`,null,`这不是说，我没有任何机会。我是说，你知道，我只是在等一个完美的男人。我要去见罗杰，好吗？他不是十全十美，但我想也许我应该结束这一切。你知道，把我的花给他。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1073.28`,duration:`5.88`}),c[974]||=a(),c[975]||=n(`strong`,null,`Rachel Green:`,-1),c[976]||=a(` Oh my God!! Do it!! Honey, you’ve waited long enough!!`,-1),c[977]||=n(`blockquote`,null,[n(`p`,null,`哦，我的天哪！！做吧！！亲爱的，你等得够久了！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1079.16`,duration:`3.432`}),c[978]||=a(),c[979]||=n(`strong`,null,`Monica Geller:`,-1),c[980]||=a(` Y’know what? You are right?!`,-1),c[981]||=n(`blockquote`,null,[n(`p`,null,`你知道吗？你是对的？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1082.592`,duration:`12.504`}),c[982]||=a(),c[983]||=n(`strong`,null,`Rachel Green:`,-1),c[984]||=a(` Yes!! I mean sex does not have to be a big deal! There shouldn’t be all this rules and restrictions! Y’know, people should be able to sleep with who ever they want, whenever…`,-1),c[985]||=n(`blockquote`,null,[n(`p`,null,`是的！！我的意思是性没什么大不了的！不应该有这些规则和限制！你知道，人们应该可以和他们想要的人睡觉，无论何时…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1095.096`,duration:`5.52`}),c[986]||=a(),c[987]||=n(`strong`,null,`Monica Geller:`,-1),c[988]||=a(` Rachel! I’m never gonna think it’s okay for you to cheat on your husband!`,-1),c[989]||=n(`blockquote`,null,[n(`p`,null,`瑞秋！我永远不会认为你背叛你丈夫是可以的！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1100.616`,duration:`3.384`}),c[990]||=a(),c[991]||=n(`strong`,null,`Rachel Green:`,-1),c[992]||=a(` Oh what do you know? Virgin!`,-1),c[993]||=n(`blockquote`,null,[n(`p`,null,`哦，你知道什么？处女！`)],-1),c[994]||=n(`hr`,null,null,-1),c[995]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`The hospital, Ross and Monica are in Phoebe’s room. Phoebe is in the bathroom and Monica notices smoke coming out from underneath the door.`)],-1),c[996]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`医院，罗斯和莫妮卡在菲比的房间里。菲比在浴室，莫妮卡注意到门下冒出烟来。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1104.0`,duration:`3.456`}),c[997]||=a(),c[998]||=n(`strong`,null,`Monica Geller:`,-1),c[999]||=a(` Phoebe, why is smoke coming out of the bathroom?!`,-1),c[1e3]||=n(`blockquote`,null,[n(`p`,null,`菲比，为什么有烟从浴室冒出来？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1107.456`,duration:`3.168`}),c[1001]||=a(),c[1002]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1003]||=a(` Oh yeah, the doctor said that could be one of the side effects.`,-1),c[1004]||=n(`blockquote`,null,[n(`p`,null,`哦，是的，医生说那可能是副作用之一。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1110.624`,duration:`3.792`}),c[1005]||=a(),c[1006]||=n(`strong`,null,`Monica Geller:`,-1),c[1007]||=a(` Phoebe! Put that cigarette out!`,-1),c[1008]||=n(`blockquote`,null,[n(`p`,null,`菲比！把香烟熄了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1114.416`,duration:`4.32`}),c[1009]||=a(),c[1010]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1011]||=a(` No! It’s not a cigarette! The smoke is coming out of me!`,-1),c[1012]||=n(`blockquote`,null,[n(`p`,null,`不！这不是香烟！烟从我身上冒出来了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1118.736`,duration:`1.704`}),c[1013]||=a(),c[1014]||=n(`strong`,null,`Monica Geller:`,-1),c[1015]||=a(` Put it out!!`,-1),c[1016]||=n(`blockquote`,null,[n(`p`,null,`把它关掉！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1120.44`,duration:`3.192`}),c[1017]||=a(),c[1018]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1019]||=a(` Okay! Okay! (Puts it out and comes out of the bathroom.) I’m so glad you’re here.`,-1),c[1020]||=n(`blockquote`,null,[n(`p`,null,`好的！可以（把它拿出来，走出浴室）我很高兴你在这里。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1123.632`,duration:`3.072`}),c[1021]||=a(),c[1022]||=n(`strong`,null,`Ross Geller:`,-1),c[1023]||=a(` Come on. (Helps her into bed as her phone rings.) I got it.`,-1),c[1024]||=n(`blockquote`,null,[n(`p`,null,`来吧。（电话铃响时帮她上床。）我知道了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1126.704`,duration:`1.368`}),c[1025]||=a(),c[1026]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1027]||=a(` Oh, give it to me.`,-1),c[1028]||=n(`blockquote`,null,[n(`p`,null,`哦，给我。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1128.072`,duration:`1.656`}),c[1029]||=a(),c[1030]||=n(`strong`,null,`Ross Geller:`,-1),c[1031]||=a(` I got it!`,-1),c[1032]||=n(`blockquote`,null,[n(`p`,null,`我明白了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1129.728`,duration:`0.912`}),c[1033]||=a(),c[1034]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1035]||=a(` Give it!`,-1),c[1036]||=n(`blockquote`,null,[n(`p`,null,`给我！`)],-1),c[1037]||=n(`p`,null,[n(`em`,null,`(He does a kara-tay move to silence her, then answers the phone.)`)],-1),c[1038]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（他用卡拉·泰的动作让她安静下来，然后接了电话。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1130.64`,duration:`8.952`}),c[1039]||=a(),c[1040]||=n(`strong`,null,`Ross Geller:`,-1),c[1041]||=a(` (on the phone) Hello? (Listens.) No she can’t come to the phone right now. (Listens.) Oh, right no problem. Okay, bye-bye. (Hangs up.)`,-1),c[1042]||=n(`blockquote`,null,[n(`p`,null,`（在电话里）喂？（听）不，她现在不能来接电话。（听）哦，好的，没问题。好的，再见。（挂断。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1139.592`,duration:`4.896`}),c[1043]||=a(),c[1044]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1045]||=a(` Was it my work? Were they mad? Was it Jack? Did he yell?!`,-1),c[1046]||=n(`blockquote`,null,[n(`p`,null,`是我的工作吗？他们疯了吗？是杰克吗？他喊了吗？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1144.488`,duration:`7.056`}),c[1047]||=a(),c[1048]||=n(`strong`,null,`Ross Geller:`,-1),c[1049]||=a(` J-j-just relax, nobody yelled. Jack just was calling to make sure that you were getting better.`,-1),c[1050]||=n(`blockquote`,null,[n(`p`,null,`放松点，没人喊。杰克只是打电话来确认你的病情好转了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1151.544`,duration:`1.08`}),c[1051]||=a(),c[1052]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1053]||=a(` Thank God.`,-1),c[1054]||=n(`blockquote`,null,[n(`p`,null,`感谢上帝。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1152.624`,duration:`2.4`}),c[1055]||=a(),c[1056]||=n(`strong`,null,`Ross Geller:`,-1),c[1057]||=a(` (To Monica) Yeah, she’s fired.`,-1),c[1058]||=n(`blockquote`,null,[n(`p`,null,`（对莫妮卡）是的，她被解雇了。`)],-1),c[1059]||=n(`hr`,null,null,-1),c[1060]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Rachel and Barry’s bedroom, Rachel is watching Days of Our Lives. Of course it’s a Dr. Drake Remoray scene. It’s set in a hospital room, and Dr. Wesley and a nurse are talking about a female patient with a bandage around her head.`)],-1),c[1061]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`瑞秋和巴里的卧室，瑞秋正在看我们的生活。当然这是德雷克医生的一个场景。场景设置在一间病房，韦斯利医生和一名护士正在谈论一名头上缠着绷带的女病人。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1155.024`,duration:`3.168`}),c[1062]||=o(` <strong>Nurse:</strong> You’ve done all you can Dr. Wesley. You have got to let her go.<blockquote><p>韦斯利医生，你已经尽力了。你必须让她走。</p></blockquote><p>Dr. Wesley: Good-bye and God speed, Hope Brady.</p><blockquote><p>再见，上帝保佑，希望布雷迪。</p></blockquote><p><em>(He goes to turn off a machine. Suddenly, Dr. Drake Remoray appears at the door with two cops!)</em></p><blockquote><p><em>（他去关掉一台机器。突然，德雷克·雷莫雷博士和两名警察出现在门口！）</em></p></blockquote><p>Dr. Drake Remoray: Not so fast Wesley! (Rachel does a silent clap.)</p><blockquote><p>别那么快，卫斯理！（瑞秋无声地鼓掌。）</p></blockquote><p>Dr. Wesley: (with evil dripping off his tongue) Remoray!</p><blockquote><p>（舌头上滴下邪恶的泪水）雷！</p></blockquote><p>Dr. Drake Remoray: That’s right Wesley! I just stopped by to say that, you’re not a real doctor! And that woman’s brain, is fine!</p><blockquote><p>没错，卫斯理！我只是顺便说一下，你不是一个真正的医生！那个女人的大脑，很好！</p></blockquote>`,14),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1158.192`,duration:`3.0`}),c[1063]||=a(),c[1064]||=n(`strong`,null,`Rachel Green:`,-1),c[1065]||=a(` (very relived) Oh! Thank God!`,-1),c[1066]||=n(`blockquote`,null,[n(`p`,null,`（非常兴奋）哦！感谢上帝！`)],-1),c[1067]||=n(`p`,null,`[Cut back to the TV, the cops are leading Dr. Wesley out, and as they pass Remoray and Wesley exchange evil glances.]`,-1),c[1068]||=n(`blockquote`,null,[n(`p`,null,`[回到电视上，警察正把卫斯理医生带出去，当他们经过雷莫雷时，卫斯理恶狠狠地瞪了他一眼。]`)],-1),c[1069]||=n(`p`,null,`Dr. Drake Remoray: Hope! Hope!`,-1),c[1070]||=n(`blockquote`,null,[n(`p`,null,`希望！希望`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1161.192`,duration:`0.816`}),c[1071]||=a(),c[1072]||=n(`strong`,null,`Hope:`,-1),c[1073]||=a(` (sleepily) Drake!`,-1),c[1074]||=n(`blockquote`,null,[n(`p`,null,`（睡意朦胧）德雷克！`)],-1),c[1075]||=n(`p`,null,`Dr. Drake Remoray: You’re not dying Hope, you’re gonna live a long, healthy life. With me.`,-1),c[1076]||=n(`blockquote`,null,[n(`p`,null,`你不会死，希望你能健康长寿。和我一起。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1162.008`,duration:`0.984`}),c[1077]||=a(),c[1078]||=n(`strong`,null,`Hope:`,-1),c[1079]||=a(` Oh Drake.`,-1),c[1080]||=n(`blockquote`,null,[n(`p`,null,`噢，德雷克。`)],-1),c[1081]||=n(`p`,null,`[Drake and Hope kiss.]`,-1),c[1082]||=n(`blockquote`,null,[n(`p`,null,`[德雷克和希望之吻。]`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1162.992`,duration:`14.664`}),c[1083]||=o(` <strong>Rachel Green:</strong> Okay! (She picks up the phone, Joey’s phone number, and starts to dial.) Here we go! Okay! (On phone.) Hi, Joey! It’s Rachel! Umm, I am free tomorrow night. Yeah, sure, sure I can bring some sandwiches.<blockquote><p>好的！（她拿起电话，乔伊的电话号码，开始拨号。）开始！可以（打电话）嗨，乔伊！是瑞秋！嗯，我明晚有空。是的，当然，当然，我可以带一些三明治。</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><p>{Transcriber’s Note: This is where Part II begins, which means this is now episode 616.}</p><blockquote><p>{转录者注：这是第二部分的开始，也就是说现在是第616集。}</p></blockquote><hr><p>🎬 <em>Ross and Carol&#39;s, Carol is working on something at the table and Ross is reading a newspaper on the couch.</em></p><blockquote><p>🎬 <em>罗斯和卡萝家，卡萝正在桌子上做什么，罗斯在沙发上看报纸。</em></p></blockquote>`,11),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1177.656`,duration:`5.856`}),c[1084]||=a(),c[1085]||=n(`strong`,null,`Ross Geller:`,-1),c[1086]||=a(` So honey this uh, this threesome thing umm, I mean how-how are you gonna start to find…`,-1),c[1087]||=n(`blockquote`,null,[n(`p`,null,`亲爱的，这件三人行的事，嗯，我是说你要怎么开始找到…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1183.512`,duration:`5.112`}),c[1088]||=a(),c[1089]||=n(`strong`,null,`Carol Willick:`,-1),c[1090]||=a(` Ooh, actually I’ve been making a list of all the women I know who might be into doing this!`,-1),c[1091]||=n(`blockquote`,null,[n(`p`,null,`哦，事实上，我一直在列一个清单，列出我认识的所有可能会做这件事的女人！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1188.624`,duration:`8.472`}),c[1092]||=a(),c[1093]||=n(`strong`,null,`Ross Geller:`,-1),c[1094]||=a(` Oh. (He takes the notepad she was using and looks at it.) Wow! (Flips to another page.) Huh. (Flips another page.) Boy! (Flips another page.) Well, someone’s been doing their homework. (Flips two more pages.)`,-1),c[1095]||=n(`blockquote`,null,[n(`p`,null,`哦。（他拿起她正在用的记事本看了看。）哇！（翻到另一页）嗯。（翻另一页）小子！（翻另一页）嗯，有人在做作业。（再翻两页。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1197.096`,duration:`5.136`}),c[1096]||=a(),c[1097]||=n(`strong`,null,`Carol Willick:`,-1),c[1098]||=a(` Yeah. Ooh, and I know Gail Rosten is in there twice, but she is so…`,-1),c[1099]||=n(`blockquote`,null,[n(`p`,null,`是的。哦，我知道盖尔·罗斯顿在那里两次，但她太…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1202.232`,duration:`5.904`}),c[1100]||=a(),c[1101]||=n(`strong`,null,`Ross Geller:`,-1),c[1102]||=a(` Oh, I know. (Laughs) Y’know, just-just talking about it is getting me kinda…`,-1),c[1103]||=n(`blockquote`,null,[n(`p`,null,`哦，我知道。（笑）你知道，仅仅是谈论它就让我有点…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1208.136`,duration:`1.344`}),c[1104]||=a(),c[1105]||=n(`strong`,null,`Carol Willick:`,-1),c[1106]||=a(` Oh, me too.`,-1),c[1107]||=n(`blockquote`,null,[n(`p`,null,`哦，我也是。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1209.48`,duration:`4.368`}),c[1108]||=a(),c[1109]||=n(`strong`,null,`Ross Geller:`,-1),c[1110]||=a(` Yeah? Well, I-I think Ben’s asleep.`,-1),c[1111]||=n(`blockquote`,null,[n(`p`,null,`是吗？我想本睡着了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1213.848`,duration:`3.696`}),c[1112]||=a(),c[1113]||=n(`strong`,null,`Carol Willick:`,-1),c[1114]||=a(` Oh umm, y’know I think it would be better if we just save it.`,-1),c[1115]||=n(`blockquote`,null,[n(`p`,null,`哦，嗯，你知道，我想如果我们把它存起来会更好。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1217.544`,duration:`6.024`}),c[1116]||=a(),c[1117]||=n(`strong`,null,`Ross Geller:`,-1),c[1118]||=a(` Yeah. Right. Save it. I can do that. (Gets up and does a little kara-tay.)`,-1),c[1119]||=n(`blockquote`,null,[n(`p`,null,`是的。正确的。保存它。我能做到。（站起来做了一个小卡拉·泰。）`)],-1),c[1120]||=n(`hr`,null,null,-1),c[1121]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`The hospital, Chandler and Monica are there with Phoebe as Ross enters.`)],-1),c[1122]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`罗斯进来时，医院、钱德勒和莫妮卡与菲比在一起。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1223.568`,duration:`2.136`}),c[1123]||=a(),c[1124]||=n(`strong`,null,`Ross Geller:`,-1),c[1125]||=a(` Hey, Pheebs!`,-1),c[1126]||=n(`blockquote`,null,[n(`p`,null,`嘿，菲比！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1225.704`,duration:`0.744`}),c[1127]||=a(),c[1128]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1129]||=a(` Hey.`,-1),c[1130]||=n(`blockquote`,null,[n(`p`,null,`嘿。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1226.448`,duration:`2.328`}),c[1131]||=a(),c[1132]||=n(`strong`,null,`Ross Geller:`,-1),c[1133]||=a(` Hey, how’s it going?`,-1),c[1134]||=n(`blockquote`,null,[n(`p`,null,`嘿，最近怎么样？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1228.776`,duration:`4.2`}),c[1135]||=a(),c[1136]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1137]||=a(` Well, I’ve got to get out of this bed, I’m going crazy here. Crazy!`,-1),c[1138]||=n(`blockquote`,null,[n(`p`,null,`嗯，我得起床了，我快疯了。疯子`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1232.976`,duration:`2.064`}),c[1139]||=a(),c[1140]||=n(`strong`,null,`Monica Geller:`,-1),c[1141]||=a(` (handing her a cup) Here you go sweetie.`,-1),c[1142]||=n(`blockquote`,null,[n(`p`,null,`（递给她一杯）给你，亲爱的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1235.04`,duration:`3.528`}),c[1143]||=a(),c[1144]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1145]||=a(` What the hell is this, herbal tea? I hate herbal tea!`,-1),c[1146]||=n(`blockquote`,null,[n(`p`,null,`这到底是什么，草药茶？我讨厌草药茶！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1238.568`,duration:`2.688`}),c[1147]||=a(),c[1148]||=n(`strong`,null,`Monica Geller:`,-1),c[1149]||=a(` But, I put some honey in it.`,-1),c[1150]||=n(`blockquote`,null,[n(`p`,null,`但是，我放了一些蜂蜜在里面。`)],-1),c[1151]||=n(`p`,null,[n(`em`,null,`(Phoebe mocks what Monica just said. Ross pulls Chandler aside.)`)],-1),c[1152]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（菲比嘲笑莫妮卡刚才说的话。罗斯把钱德勒拉到一边。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1241.256`,duration:`3.432`}),c[1153]||=a(),c[1154]||=n(`strong`,null,`Ross Geller:`,-1),c[1155]||=a(` She doesn’t know she was fired yet, does she?`,-1),c[1156]||=n(`blockquote`,null,[n(`p`,null,`她还不知道自己被解雇了，是吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1244.688`,duration:`3.288`}),c[1157]||=a(),c[1158]||=n(`strong`,null,`Chandler Bing:`,-1),c[1159]||=a(` No, the doctors say it may kill her.`,-1),c[1160]||=n(`blockquote`,null,[n(`p`,null,`不，医生说可能会杀了她。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1247.976`,duration:`2.88`}),c[1161]||=a(),c[1162]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1163]||=a(` What are you two girls whispering about over there?!`,-1),c[1164]||=n(`blockquote`,null,[n(`p`,null,`你们两个女孩在那边小声说什么？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1250.856`,duration:`2.376`}),c[1165]||=a(),c[1166]||=n(`strong`,null,`Chandler Bing:`,-1),c[1167]||=a(` (To Ross) But I think we should tell her.`,-1),c[1168]||=n(`blockquote`,null,[n(`p`,null,`（对罗斯）但我想我们应该告诉她。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1253.232`,duration:`7.056`}),c[1169]||=a(),c[1170]||=n(`strong`,null,`Ross Geller:`,-1),c[1171]||=a(` Hey Pheebs, maybe this whole heart attack thing is a sign, that-that you should start think about getting a different job.`,-1),c[1172]||=n(`blockquote`,null,[n(`p`,null,`嘿，菲比，也许这整件心脏病发作的事情是一个信号，你应该开始考虑换一份工作。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1260.288`,duration:`4.896`}),c[1173]||=a(),c[1174]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1175]||=a(` Okay, what is this? A stupid contest? Because we got a winner here! (Points at Ross.)`,-1),c[1176]||=n(`blockquote`,null,[n(`p`,null,`好吧，这是什么？愚蠢的比赛？因为我们这里有个赢家！（指着罗斯。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1265.184`,duration:`6.576`}),c[1177]||=a(),c[1178]||=n(`strong`,null,`Chandler Bing:`,-1),c[1179]||=a(` Listen Phoebe, he’s right. People are not supposed to have heart attacks at 31.`,-1),c[1180]||=n(`blockquote`,null,[n(`p`,null,`听着，菲比，他是对的。人们不应该在31岁时心脏病发作。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1271.76`,duration:`3.72`}),c[1181]||=a(),c[1182]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1183]||=a(` I know! But if I didn’t work there, what else would I do?`,-1),c[1184]||=n(`blockquote`,null,[n(`p`,null,`我知道！但如果我不在那里工作，我还能做什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1275.48`,duration:`3.216`}),c[1185]||=a(),c[1186]||=n(`strong`,null,`Monica Geller:`,-1),c[1187]||=a(` Well, you used to like playing the guitar.`,-1),c[1188]||=n(`blockquote`,null,[n(`p`,null,`嗯，你以前喜欢弹吉他。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1278.696`,duration:`3.408`}),c[1189]||=a(),c[1190]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1191]||=a(` Yeah that was lucrative! Smart like your brother!`,-1),c[1192]||=n(`blockquote`,null,[n(`p`,null,`是啊，那是有利可图的！像你哥哥一样聪明！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1282.104`,duration:`5.976`}),c[1193]||=a(),c[1194]||=n(`strong`,null,`Chandler Bing:`,-1),c[1195]||=a(` Uh, what about y’know the massage thing? That never gave you a heart attack.`,-1),c[1196]||=n(`blockquote`,null,[n(`p`,null,`嗯，你知道按摩的事吗？那从来没有让你心脏病发作过。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1288.08`,duration:`8.664`}),c[1197]||=a(),c[1198]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1199]||=a(` Hmm, pulling in a salary in the high six figures or rubbing gross naked people for chump change—ooh, what do I do?! What will I do?!`,-1),c[1200]||=n(`blockquote`,null,[n(`p`,null,`嗯，拿高六位数的薪水，或者用裸体来换零钱哦，我该怎么办？！我该怎么办？！`)],-1),c[1201]||=n(`hr`,null,null,-1),c[1202]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Joey's apartment, (The one he had when he was Dr. Drake Remoray, because he still is.) Rachel is there and admiring the big ceramic fake dog.`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1296.744`,duration:`3.192`}),c[1203]||=a(),c[1204]||=n(`strong`,null,`Rachel Green:`,-1),c[1205]||=a(` Ohh, I mean it’s just so realistic!`,-1),c[1206]||=n(`blockquote`,null,[n(`p`,null,`哦，我是说它太现实了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1299.936`,duration:`4.032`}),c[1207]||=a(),c[1208]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1209]||=a(` I know. (Joey is sitting in this tall chair that is made up of balls on polls. You’ll have to see it to know what I mean.) Yeah, his name is Pat.`,-1),c[1210]||=n(`blockquote`,null,[n(`p`,null,`我知道。（乔伊坐在这把高椅子上，椅子上有很多球，你得看看才能明白我的意思。）是的，他的名字叫帕特。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1303.968`,duration:`5.976`}),c[1211]||=a(),c[1212]||=n(`strong`,null,`Rachel Green:`,-1),c[1213]||=a(` Pat the dog. Oh! Oh! I get it!! (Laughs and finishes her drink.)`,-1),c[1214]||=n(`blockquote`,null,[n(`p`,null,`拍狗。哦哦我明白了！！（笑着喝完了她的饮料。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1309.944`,duration:`3.12`}),c[1215]||=a(),c[1216]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1217]||=a(` (climbing down from his chair) Do you uh, do you—ready for a refill?`,-1),c[1218]||=n(`blockquote`,null,[n(`p`,null,`（从椅子上爬下来）你准备好了吗？你准备好要续杯了吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1313.064`,duration:`7.968`}),c[1219]||=a(),c[1220]||=n(`strong`,null,`Rachel Green:`,-1),c[1221]||=a(` Oh, I probably shouldn’t—so I will! (Joey starts making her refill and Rachel notices that rain thing Joey has.) Oh! Wow! It’s like it’s raining!`,-1),c[1222]||=n(`blockquote`,null,[n(`p`,null,`哦，我可能不应该——所以我会的！（乔伊开始给她续杯，瑞秋注意到乔伊有雨。）哦！哇！好像在下雨！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1321.032`,duration:`8.424`}),c[1223]||=a(),c[1224]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1225]||=a(` Pretty cool, huh? But if you’re thinking you can put a fish in there and it wouldn’t get sucked up into the mechanism, well you’d be wrong.`,-1),c[1226]||=n(`blockquote`,null,[n(`p`,null,`很酷吧？但是如果你认为你可以把一条鱼放在里面，而它不会被吸入机械装置，那么你就错了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1329.456`,duration:`2.592`}),c[1227]||=a(),c[1228]||=n(`strong`,null,`Rachel Green:`,-1),c[1229]||=a(` Umm, can I use your bathroom?`,-1),c[1230]||=n(`blockquote`,null,[n(`p`,null,`嗯，我能用一下你的浴室吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1332.048`,duration:`2.472`}),c[1231]||=a(),c[1232]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1233]||=a(` It’s uh, right through there. (Points.)`,-1),c[1234]||=n(`blockquote`,null,[n(`p`,null,`就在那边。（点数）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1334.52`,duration:`7.056`}),c[1235]||=a(),c[1236]||=n(`strong`,null,`Rachel Green:`,-1),c[1237]||=a(` Okay. (Starts to go.) God y’know, if someone told me a week ago that I would be peeing in Joey Tribbiani’s apartment…`,-1),c[1238]||=n(`blockquote`,null,[n(`p`,null,`好的。天啊，你知道，如果一周前有人告诉我我会在乔伊·特里比亚尼的公寓里撒尿…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1341.576`,duration:`2.856`}),c[1239]||=a(),c[1240]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1241]||=a(` Yeah, life’s pretty great isn’t it?`,-1),c[1242]||=n(`blockquote`,null,[n(`p`,null,`是啊，生活很美好，不是吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1344.432`,duration:`2.328`}),c[1243]||=a(),c[1244]||=n(`strong`,null,`Rachel Green:`,-1),c[1245]||=a(` Yeah, it sure is!`,-1),c[1246]||=n(`blockquote`,null,[n(`p`,null,`是的，的确如此！`)],-1),c[1247]||=n(`hr`,null,null,-1),c[1248]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Phoebe's, Monica is pouring wine for her boyfriend, Dr. Roger.`)],-1),c[1249]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和菲比家，莫妮卡正在为她的男朋友罗杰医生斟酒。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1346.76`,duration:`6.96`}),c[1250]||=a(),c[1251]||=n(`strong`,null,`Monica Geller:`,-1),c[1252]||=a(` I hope you’re hungry, we’re starting with oysters. And y’know what they say about oysters, don’t you?`,-1),c[1253]||=n(`blockquote`,null,[n(`p`,null,`我希望你饿了，我们从牡蛎开始。你知道人们怎么说牡蛎吗？`)],-1),c[1254]||=n(`p`,null,`Dr. Roger: They have parasites?`,-1),c[1255]||=n(`blockquote`,null,[n(`p`,null,`他们有寄生虫？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1353.72`,duration:`5.856`}),c[1256]||=a(),c[1257]||=n(`strong`,null,`Monica Geller:`,-1),c[1258]||=a(` No! Umm well, some people say that Oysters are an aphrodisiac.`,-1),c[1259]||=n(`blockquote`,null,[n(`p`,null,`不！嗯，有人说牡蛎有壮阳作用。`)],-1),c[1260]||=n(`p`,null,`Dr. Roger: What people?`,-1),c[1261]||=n(`blockquote`,null,[n(`p`,null,`什么人？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1359.576`,duration:`4.896`}),c[1262]||=a(),c[1263]||=n(`strong`,null,`Monica Geller:`,-1),c[1264]||=a(` People! People say it! Come here! (She grabs him and kisses him.)`,-1),c[1265]||=n(`blockquote`,null,[n(`p`,null,`人们！人们都这么说！过来！（她抓住他，吻了吻他。）`)],-1),c[1266]||=n(`p`,null,`Dr. Roger: So oysters, huh?`,-1),c[1267]||=n(`blockquote`,null,[n(`p`,null,`那么牡蛎呢？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1364.472`,duration:`6.72`}),c[1268]||=a(),c[1269]||=n(`strong`,null,`Monica Geller:`,-1),c[1270]||=a(` And then we’re gonna have a little Middle Eastern cous-cous. Something we can eat, with our hands.`,-1),c[1271]||=n(`blockquote`,null,[n(`p`,null,`然后我们要一点中东粗麦粉。我们可以用手吃的东西。`)],-1),c[1272]||=n(`p`,null,`Dr. Roger: Y’know, it’s funny, but when we were studying communicable diseases…`,-1),c[1273]||=n(`blockquote`,null,[n(`p`,null,`你知道，这很有趣，但是当我们研究传染病的时候…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1371.192`,duration:`4.056`}),c[1274]||=a(),c[1275]||=n(`strong`,null,`Monica Geller:`,-1),c[1276]||=a(` No-no-no, no! It’s sensual!`,-1),c[1277]||=n(`blockquote`,null,[n(`p`,null,`不，不，不！这是性感的！`)],-1),c[1278]||=n(`p`,null,`Dr. Roger: Ohh! Didn’t know! Okay!`,-1),c[1279]||=n(`blockquote`,null,[n(`p`,null,`哦！我不知道！可以`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1375.248`,duration:`3.048`}),c[1280]||=a(),c[1281]||=n(`strong`,null,`Monica Geller:`,-1),c[1282]||=a(` Okay! (They kiss again and his beeper goes off.) Ohhh no!`,-1),c[1283]||=n(`blockquote`,null,[n(`p`,null,`好的！（他们又接吻了，他的呼机响了。）哦，不！`)],-1),c[1284]||=n(`p`,null,`Dr. Roger: I’m sorry sweetie, it’s the hospital. The food looks great, maybe save me some?`,-1),c[1285]||=n(`blockquote`,null,[n(`p`,null,`对不起，亲爱的，是医院。食物看起来很棒，也许能给我留点？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1378.296`,duration:`2.4`}),c[1286]||=a(),c[1287]||=n(`strong`,null,`Monica Geller:`,-1),c[1288]||=a(` I can’t promise anything. (She starts to dig in.)`,-1),c[1289]||=n(`blockquote`,null,[n(`p`,null,`我不能答应任何事。（她开始埋头钻研。）`)],-1),c[1290]||=n(`hr`,null,null,-1),c[1291]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Ross and Carol's, Ross and Carol are waiting anxiously for their new partner to arrive.`)],-1),c[1292]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`罗斯和卡萝家，罗斯和卡萝焦急地等待他们的新伴侣到来。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1380.696`,duration:`2.616`}),c[1293]||=a(),c[1294]||=n(`strong`,null,`Ross Geller:`,-1),c[1295]||=a(` We’re really gonna do this, huh?`,-1),c[1296]||=n(`blockquote`,null,[n(`p`,null,`我们真的要这么做，嗯？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1383.312`,duration:`1.224`}),c[1297]||=a(),c[1298]||=n(`strong`,null,`Carol Willick:`,-1),c[1299]||=a(` Looks like it.`,-1),c[1300]||=n(`blockquote`,null,[n(`p`,null,`看起来像。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1384.536`,duration:`5.136`}),c[1301]||=a(),c[1302]||=n(`strong`,null,`Ross Geller:`,-1),c[1303]||=a(` Y’know, if, if this is too weird for you, we can still back out at… (A knock on the door interrupts him.)`,-1),c[1304]||=n(`blockquote`,null,[n(`p`,null,`你知道，如果，如果这对你来说太奇怪了，我们还是可以在…（敲门打断了他。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1389.672`,duration:`1.248`}),c[1305]||=a(),c[1306]||=n(`strong`,null,`Carol Willick:`,-1),c[1307]||=a(` (jumping up to get it) I got it!`,-1),c[1308]||=n(`blockquote`,null,[n(`p`,null,`（跳起来拿）我明白了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1390.92`,duration:`1.512`}),c[1309]||=a(),c[1310]||=n(`strong`,null,`Ross Geller:`,-1),c[1311]||=a(` Okay.`,-1),c[1312]||=n(`blockquote`,null,[n(`p`,null,`好的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1392.432`,duration:`1.92`}),c[1313]||=a(),c[1314]||=n(`strong`,null,`Carol Willick:`,-1),c[1315]||=a(` (opening the door) Susan! Hi! (Who’d you think it was gonna be?)`,-1),c[1316]||=n(`blockquote`,null,[n(`p`,null,`（开门）苏珊！你好（你以为会是谁？）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1394.352`,duration:`1.368`}),c[1317]||=a(),c[1318]||=n(`strong`,null,`Susan Bunch:`,-1),c[1319]||=a(` Hey! (They hug.)`,-1),c[1320]||=n(`blockquote`,null,[n(`p`,null,`嘿！（他们拥抱。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1395.72`,duration:`2.184`}),c[1321]||=a(),c[1322]||=n(`strong`,null,`Carol Willick:`,-1),c[1323]||=a(` Thank you so much for coming.`,-1),c[1324]||=n(`blockquote`,null,[n(`p`,null,`非常感谢你的光临。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1397.904`,duration:`3.192`}),c[1325]||=a(),c[1326]||=n(`strong`,null,`Susan Bunch:`,-1),c[1327]||=a(` Oh, I wouldn’t miss it for the world.`,-1),c[1328]||=n(`blockquote`,null,[n(`p`,null,`哦，我绝对不会错过的。`)],-1),c[1329]||=n(`p`,null,[n(`em`,null,`(They start moving towards the bedroom, never taking their eyes off each other. They move past Ross and stop.)`)],-1),c[1330]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（他们开始朝卧室走去，眼睛一直盯着对方。他们从罗斯身边走过，停了下来。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1401.096`,duration:`2.424`}),c[1331]||=a(),c[1332]||=n(`strong`,null,`Ross Geller:`,-1),c[1333]||=a(` I’m-I’m Ross by the way.`,-1),c[1334]||=n(`blockquote`,null,[n(`p`,null,`顺便说一下，我是罗斯。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1403.52`,duration:`5.088`}),c[1335]||=a(),c[1336]||=n(`strong`,null,`Susan Bunch:`,-1),c[1337]||=a(` (not taking her eyes off Carol) Hello Ross. (Takes off her coat and hands it to him.) I love what you’ve done with this space.`,-1),c[1338]||=n(`blockquote`,null,[n(`p`,null,`（眼睛没有离开卡萝）你好，罗斯。（脱下外套递给他）我喜欢你在这个地方所做的一切。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1408.608`,duration:`1.752`}),c[1339]||=a(),c[1340]||=n(`strong`,null,`Carol Willick:`,-1),c[1341]||=a(` Thank you so much.`,-1),c[1342]||=n(`blockquote`,null,[n(`p`,null,`非常感谢你。`)],-1),c[1343]||=n(`p`,null,[n(`em`,null,`(They disappear into the bedroom leaving Ross standing in the living room holding Susan’s coat.)`)],-1),c[1344]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（他们消失在卧室里，留下罗斯站在客厅里拿着苏珊的外套。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1410.36`,duration:`2.088`}),c[1345]||=a(),c[1346]||=n(`strong`,null,`Ross Geller:`,-1),c[1347]||=a(` How hot is this?!`,-1),c[1348]||=n(`blockquote`,null,[n(`p`,null,`这有多热？！`)],-1),c[1349]||=n(`hr`,null,null,-1),c[1350]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Phoebe's, Chandler and Monica are eating Monica’s dinner.`)],-1),c[1351]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和菲比的，钱德勒和莫妮卡正在吃莫妮卡的晚餐。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1412.448`,duration:`3.336`}),c[1352]||=a(),c[1353]||=n(`strong`,null,`Chandler Bing:`,-1),c[1354]||=a(` I’m sorry you’re here with me instead of Roger.`,-1),c[1355]||=n(`blockquote`,null,[n(`p`,null,`很抱歉，你代替罗杰和我在一起。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1415.784`,duration:`2.184`}),c[1356]||=a(),c[1357]||=n(`strong`,null,`Monica Geller:`,-1),c[1358]||=a(` Yeah, me too.`,-1),c[1359]||=n(`blockquote`,null,[n(`p`,null,`是的，我也是。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1417.968`,duration:`10.752`}),c[1360]||=a(),c[1361]||=n(`strong`,null,`Chandler Bing:`,-1),c[1362]||=a(` Well, I could make it seem like he’s here. (Imitates him.) "Here’s some little known facts about cous-cous. They didn’t add the second cous until 1979." (Mumbles something further.)`,-1),c[1363]||=n(`blockquote`,null,[n(`p`,null,`嗯，我可以让人觉得他在这里。（模仿他。）“这里有一些鲜为人知的关于蒸粗麦粉的事实。他们直到1979年才添加第二种蒸粗麦粉。”（喃喃地说了些更进一步的话。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1428.72`,duration:`3.624`}),c[1364]||=a(),c[1365]||=n(`strong`,null,`Monica Geller:`,-1),c[1366]||=a(` Stop it!! That’s not funny!!`,-1),c[1367]||=n(`blockquote`,null,[n(`p`,null,`住手！！那不好笑！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1432.344`,duration:`1.56`}),c[1368]||=a(),c[1369]||=n(`strong`,null,`Chandler Bing:`,-1),c[1370]||=a(` Okay.`,-1),c[1371]||=n(`blockquote`,null,[n(`p`,null,`好的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1433.904`,duration:`7.272`}),c[1372]||=a(),c[1373]||=n(`strong`,null,`Monica Geller:`,-1),c[1374]||=a(` I’m sorry, okay? It just—tonight was supposed to be y’know, it was supposed to be a big deal.`,-1),c[1375]||=n(`blockquote`,null,[n(`p`,null,`对不起，好吗？就在今晚，你知道，这应该是一件大事。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1441.176`,duration:`1.92`}),c[1376]||=a(),c[1377]||=n(`strong`,null,`Chandler Bing:`,-1),c[1378]||=a(` What was tonight?`,-1),c[1379]||=n(`blockquote`,null,[n(`p`,null,`今晚是什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1443.096`,duration:`2.904`}),c[1380]||=a(),c[1381]||=n(`strong`,null,`Monica Geller:`,-1),c[1382]||=a(` You don’t want to know what tonight was.`,-1),c[1383]||=n(`blockquote`,null,[n(`p`,null,`你不想知道今晚是什么。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1446.0`,duration:`3.36`}),c[1384]||=a(),c[1385]||=n(`strong`,null,`Chandler Bing:`,-1),c[1386]||=a(` Okay. (Pause.) What was tonight?`,-1),c[1387]||=n(`blockquote`,null,[n(`p`,null,`好的。（停顿）今晚是什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1449.36`,duration:`4.056`}),c[1388]||=a(),c[1389]||=n(`strong`,null,`Monica Geller:`,-1),c[1390]||=a(` Well, tonight was—was going to be my first time.`,-1),c[1391]||=n(`blockquote`,null,[n(`p`,null,`今晚是我第一次。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1453.416`,duration:`5.664`}),c[1392]||=a(),c[1393]||=n(`strong`,null,`Chandler Bing:`,-1),c[1394]||=a(` With Roger? (Monica shyly looks away.) Not just with Roger?! (Monica shrugs.) Oh my God!`,-1),c[1395]||=n(`blockquote`,null,[n(`p`,null,`和罗杰？（莫妮卡害羞地把目光移开）不仅仅是罗杰？！（莫妮卡耸耸肩）哦，天哪！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1459.08`,duration:`3.816`}),c[1396]||=a(),c[1397]||=n(`strong`,null,`Monica Geller:`,-1),c[1398]||=a(` All right relax Mr. I’ve Had Sex Four Times!`,-1),c[1399]||=n(`blockquote`,null,[n(`p`,null,`好了，放松点，先生，我已经做爱四次了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1462.896`,duration:`4.824`}),c[1400]||=a(),c[1401]||=n(`strong`,null,`Chandler Bing:`,-1),c[1402]||=a(` Four different women! I’ve had sex way more times!`,-1),c[1403]||=n(`blockquote`,null,[n(`p`,null,`四个不同的女人！我已经做爱很多次了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1467.72`,duration:`1.632`}),c[1404]||=a(),c[1405]||=n(`strong`,null,`Monica Geller:`,-1),c[1406]||=a(` How many?`,-1),c[1407]||=n(`blockquote`,null,[n(`p`,null,`多少？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1469.352`,duration:`1.536`}),c[1408]||=a(),c[1409]||=n(`strong`,null,`Chandler Bing:`,-1),c[1410]||=a(` Nine.`,-1),c[1411]||=n(`blockquote`,null,[n(`p`,null,`九点。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1470.888`,duration:`3.0`}),c[1412]||=a(),c[1413]||=n(`strong`,null,`Monica Geller:`,-1),c[1414]||=a(` I was just waiting for the perfect guy.`,-1),c[1415]||=n(`blockquote`,null,[n(`p`,null,`我只是在等一个完美的男人。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1473.888`,duration:`5.832`}),c[1416]||=a(),c[1417]||=n(`strong`,null,`Chandler Bing:`,-1),c[1418]||=a(` Well good, good for you. You really think that Roger is the perfect guy?`,-1),c[1419]||=n(`blockquote`,null,[n(`p`,null,`很好，对你很好。你真的认为罗杰是个完美的人？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1479.72`,duration:`3.792`}),c[1420]||=a(),c[1421]||=n(`strong`,null,`Monica Geller:`,-1),c[1422]||=a(` No. He’s not a horrible guy.`,-1),c[1423]||=n(`blockquote`,null,[n(`p`,null,`不，他不是个可怕的家伙。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1483.512`,duration:`2.904`}),c[1424]||=a(),c[1425]||=n(`strong`,null,`Chandler Bing:`,-1),c[1426]||=a(` Hey that’s what I tell girls about me.`,-1),c[1427]||=n(`blockquote`,null,[n(`p`,null,`嘿，我就是这么跟女孩子们说我的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1486.416`,duration:`2.976`}),c[1428]||=a(),c[1429]||=n(`strong`,null,`Monica Geller:`,-1),c[1430]||=a(` Chandler, I’m gonna die a virgin!`,-1),c[1431]||=n(`blockquote`,null,[n(`p`,null,`钱德勒，我会死得像个处女！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1489.392`,duration:`5.952`}),c[1432]||=a(),c[1433]||=n(`strong`,null,`Chandler Bing:`,-1),c[1434]||=a(` No you are not! You are sweet and wonderful and this is gonna happen for you.`,-1),c[1435]||=n(`blockquote`,null,[n(`p`,null,`不，你不是！你很可爱，很棒，这一切都会发生在你身上。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1495.344`,duration:`5.088`}),c[1436]||=a(),c[1437]||=n(`strong`,null,`Monica Geller:`,-1),c[1438]||=a(` Oh really? When? Do you wanna do it with me?`,-1),c[1439]||=n(`blockquote`,null,[n(`p`,null,`哦，真的吗？什么时候你想和我一起做吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1500.432`,duration:`1.56`}),c[1440]||=a(),c[1441]||=n(`strong`,null,`Chandler Bing:`,-1),c[1442]||=a(` Okay. (They both realize what he just said.)`,-1),c[1443]||=n(`blockquote`,null,[n(`p`,null,`好的。（他们都知道他刚才说的话。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1501.992`,duration:`1.776`}),c[1444]||=a(),c[1445]||=n(`strong`,null,`Monica Geller:`,-1),c[1446]||=a(` I was kidding.`,-1),c[1447]||=n(`blockquote`,null,[n(`p`,null,`我在开玩笑。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1503.768`,duration:`1.896`}),c[1448]||=a(),c[1449]||=n(`strong`,null,`Chandler Bing:`,-1),c[1450]||=a(` So was I.`,-1),c[1451]||=n(`blockquote`,null,[n(`p`,null,`我也是。`)],-1),c[1452]||=n(`hr`,null,null,-1),c[1453]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Joey's apartment, Rachel is now three sheets to the wind and Joey is watching her.`)],-1),c[1454]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`乔伊的公寓，瑞秋现在被风吹得三张床，乔伊看着她。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1505.664`,duration:`7.776`}),c[1455]||=a(),c[1456]||=n(`strong`,null,`Rachel Green:`,-1),c[1457]||=a(` Joey, you’re such an amazing actor! (He smiles.) How do you know where Dr. Drake Remoray leaves off and Joey Tribbiani begins?`,-1),c[1458]||=n(`blockquote`,null,[n(`p`,null,`乔伊，你真是个了不起的演员！（他微笑着）你怎么知道德雷克·雷莫雷医生从哪里离开，乔伊·特里比亚尼从哪里开始？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1513.44`,duration:`7.632`}),c[1459]||=a(),c[1460]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1461]||=a(` Well, with Dr. Drake they always tell me what to say. And with Joey, I pretty much have to make it up on my own.`,-1),c[1462]||=n(`blockquote`,null,[n(`p`,null,`嗯，对于德雷克医生，他们总是告诉我该说什么。和乔伊在一起，我几乎要自己弥补。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1521.072`,duration:`6.624`}),c[1463]||=a(),c[1464]||=n(`strong`,null,`Rachel Green:`,-1),c[1465]||=a(` Wow! Tell me something Joey—(She falls off the couch)—Whoa! I just fell right off the couch there.`,-1),c[1466]||=n(`blockquote`,null,[n(`p`,null,`哇！告诉我乔伊（她从沙发上摔下来）-哇！我刚从沙发上摔下来。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1527.696`,duration:`1.824`}),c[1467]||=a(),c[1468]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1469]||=a(` Yeah you did.`,-1),c[1470]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1529.52`,duration:`1.512`}),c[1471]||=a(),c[1472]||=n(`strong`,null,`Rachel Green:`,-1),c[1473]||=a(` Okay. (She climbs back onto the couch.)`,-1),c[1474]||=n(`blockquote`,null,[n(`p`,null,`好的。（她爬回到沙发上。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1531.032`,duration:`4.128`}),c[1475]||=a(),c[1476]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1477]||=a(` Here you go. Let me ask you a question.`,-1),c[1478]||=n(`blockquote`,null,[n(`p`,null,`给你。让我问你一个问题。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1535.16`,duration:`1.344`}),c[1479]||=a(),c[1480]||=n(`strong`,null,`Rachel Green:`,-1),c[1481]||=a(` Yeah?`,-1),c[1482]||=n(`blockquote`,null,[n(`p`,null,`是吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1536.504`,duration:`4.272`}),c[1483]||=a(),c[1484]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1485]||=a(` When was the last time someone told you just how beautiful you are?`,-1),c[1486]||=n(`blockquote`,null,[n(`p`,null,`上次有人告诉你你有多漂亮是什么时候？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1540.776`,duration:`4.416`}),c[1487]||=a(),c[1488]||=n(`strong`,null,`Rachel Green:`,-1),c[1489]||=a(` Wow! I can’t, I can’t feel my hands.`,-1),c[1490]||=n(`blockquote`,null,[n(`p`,null,`哇！我不能，我感觉不到我的手。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1545.192`,duration:`2.016`}),c[1491]||=o(` <strong>Joey Tribbiani:</strong> Come, come here.<blockquote><p>过来，过来。</p></blockquote><p><em>(He takes her hands in his and kisses each one, then kisses her on the lips. When the break the kiss, Rachel starts to get nauseous and throw up. Joey backs away in horror.)</em></p><blockquote><p><em>（他握着她的手，吻了每一个人，然后吻了她的嘴唇。当他打断吻时，瑞秋开始恶心呕吐。乔伊吓得往后退。）</em></p></blockquote><hr><p>🎬 <em>Monica and Phoebe&#39;s, continued from earlier. Monica and Chandler are still discussing the previous question.</em></p><blockquote><p>🎬 <em>莫妮卡和菲比的，从前面继续。莫妮卡和钱德勒仍在讨论前面的问题。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1547.208`,duration:`2.184`}),c[1492]||=a(),c[1493]||=n(`strong`,null,`Chandler Bing:`,-1),c[1494]||=a(` We can’t do this.`,-1),c[1495]||=n(`blockquote`,null,[n(`p`,null,`我们不能这么做。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1549.392`,duration:`3.0`}),c[1496]||=a(),c[1497]||=n(`strong`,null,`Monica Geller:`,-1),c[1498]||=a(` No! (They both laugh.) Oyster?`,-1),c[1499]||=n(`blockquote`,null,[n(`p`,null,`不！（他们都笑了。）牡蛎？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1552.392`,duration:`10.296`}),c[1500]||=a(),c[1501]||=n(`strong`,null,`Chandler Bing:`,-1),c[1502]||=a(` Yeah! (Takes it.) If-if-if we did do this there would be a lot of pressure on me, y’know? Because you’ve been waiting a very long time and I wouldn’t want to disappoint you.`,-1),c[1503]||=n(`blockquote`,null,[n(`p`,null,`是啊！（接受）如果我们这样做，我会有很大的压力，你知道吗？因为你已经等了很长时间，我不想让你失望。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1562.688`,duration:`6.6`}),c[1504]||=a(),c[1505]||=n(`strong`,null,`Monica Geller:`,-1),c[1506]||=a(` Yeah but see I have nothing to compare it too. So even if you’re horrible, how would I know?`,-1),c[1507]||=n(`blockquote`,null,[n(`p`,null,`是啊，但我也没什么可比的。即使你很可怕，我怎么知道？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1569.288`,duration:`1.992`}),c[1508]||=a(),c[1509]||=n(`strong`,null,`Chandler Bing:`,-1),c[1510]||=a(` I do like that.`,-1),c[1511]||=n(`blockquote`,null,[n(`p`,null,`我很喜欢。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1571.28`,duration:`5.232`}),c[1512]||=a(),c[1513]||=n(`strong`,null,`Monica Geller:`,-1),c[1514]||=a(` It’s harder for me! I have those four other women to compete with!`,-1),c[1515]||=n(`blockquote`,null,[n(`p`,null,`对我来说更难！我还有另外四个女人要和我竞争！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1576.512`,duration:`6.144`}),c[1516]||=a(),c[1517]||=n(`strong`,null,`Chandler Bing:`,-1),c[1518]||=a(` Well, if it helps there were only three. So it would just be for tonight, right?`,-1),c[1519]||=n(`blockquote`,null,[n(`p`,null,`如果有帮助的话，只有三个。那就今晚吧，对吧？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1582.656`,duration:`5.376`}),c[1520]||=a(),c[1521]||=n(`strong`,null,`Monica Geller:`,-1),c[1522]||=a(` Absolutely! It would just be one friend (Points at Chandler) helping out another friend. (Points at herself.)`,-1),c[1523]||=n(`blockquote`,null,[n(`p`,null,`当然！只是一个朋友（指着钱德勒）帮助另一个朋友。（指着她自己。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1588.032`,duration:`5.184`}),c[1524]||=a(),c[1525]||=n(`strong`,null,`Chandler Bing:`,-1),c[1526]||=a(` Stop it! We’re doing this! Let’s do it!`,-1),c[1527]||=n(`blockquote`,null,[n(`p`,null,`住手！我们要这么做！让我们做吧！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1593.216`,duration:`3.096`}),c[1528]||=a(),c[1529]||=n(`strong`,null,`Monica Geller:`,-1),c[1530]||=a(` Noo!! Okay!!`,-1),c[1531]||=n(`blockquote`,null,[n(`p`,null,`不！！可以`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1596.312`,duration:`1.608`}),c[1532]||=a(),c[1533]||=n(`strong`,null,`Chandler Bing:`,-1),c[1534]||=a(` Okay! (They both get up.)`,-1),c[1535]||=n(`blockquote`,null,[n(`p`,null,`好的！（他们俩都站了起来。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1597.92`,duration:`2.976`}),c[1536]||=a(),c[1537]||=n(`strong`,null,`Monica Geller:`,-1),c[1538]||=a(` Umm, do you have any uhh, moves?`,-1),c[1539]||=n(`blockquote`,null,[n(`p`,null,`嗯，你有什么动作吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1600.896`,duration:`2.208`}),c[1540]||=a(),c[1541]||=n(`strong`,null,`Chandler Bing:`,-1),c[1542]||=a(` I have some moves.`,-1),c[1543]||=n(`blockquote`,null,[n(`p`,null,`我有一些动作。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1603.104`,duration:`9.528`}),c[1544]||=a(),c[1545]||=n(`strong`,null,`Monica Geller:`,-1),c[1546]||=a(` I have no moves. (He moves in to kiss her and she laughs and backs away.) Okay, whatcha doin’ there?! (Giggles.) Oh y’know what? I’m sorry, this is just too weird.`,-1),c[1547]||=n(`blockquote`,null,[n(`p`,null,`我没有动作。（他走进去吻她，她笑了笑，退后了。）好吧，你在那里干什么？！（笑声）哦，你知道吗？对不起，这太奇怪了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1612.632`,duration:`2.52`}),c[1548]||=a(),c[1549]||=n(`strong`,null,`Chandler Bing:`,-1),c[1550]||=a(` Yeah, let’s just forget it.`,-1),c[1551]||=n(`blockquote`,null,[n(`p`,null,`是啊，让我们忘了它吧。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1615.152`,duration:`2.52`}),c[1552]||=a(),c[1553]||=n(`strong`,null,`Monica Geller:`,-1),c[1554]||=a(` What if I turn out the lights? (Runs to shut them off.)`,-1),c[1555]||=n(`blockquote`,null,[n(`p`,null,`如果我关灯怎么办？（运行以关闭它们。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1617.672`,duration:`1.608`}),c[1556]||=a(),c[1557]||=n(`strong`,null,`Chandler Bing:`,-1),c[1558]||=a(` Okay!`,-1),c[1559]||=n(`blockquote`,null,[n(`p`,null,`好的！`)],-1),c[1560]||=n(`p`,null,[n(`em`,null,`(She turns out the lights and in the darkened room Chandler starts to moan.)`)],-1),c[1561]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（她关上灯，钱德勒在昏暗的房间里开始呻吟。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1619.28`,duration:`1.632`}),c[1562]||=a(),c[1563]||=n(`strong`,null,`Chandler Bing:`,-1),c[1564]||=a(` Oh yeah.`,-1),c[1565]||=n(`blockquote`,null,[n(`p`,null,`哦，是的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1620.912`,duration:`1.632`}),c[1566]||=a(),c[1567]||=n(`strong`,null,`Monica Geller:`,-1),c[1568]||=a(` Chandler?`,-1),c[1569]||=n(`blockquote`,null,[n(`p`,null,`钱德勒？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1622.544`,duration:`1.392`}),c[1570]||=a(),c[1571]||=n(`strong`,null,`Chandler Bing:`,-1),c[1572]||=a(` (sexily) Yeah?`,-1),c[1573]||=n(`blockquote`,null,[n(`p`,null,`（性感地）是吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1623.936`,duration:`1.992`}),c[1574]||=o(` <strong>Monica Geller:</strong> That’s the couch.<blockquote><p>那是沙发。</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica’s bedroom, she has just lost her flower to Chandler.</em></p><blockquote><p>🎬 <em>莫妮卡的卧室，她刚刚把她的花丢给了钱德勒。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1625.928`,duration:`1.92`}),c[1575]||=a(),c[1576]||=n(`strong`,null,`Chandler Bing:`,-1),c[1577]||=a(` Oh my God!`,-1),c[1578]||=n(`blockquote`,null,[n(`p`,null,`哦，我的天啊！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1627.848`,duration:`5.088`}),c[1579]||=a(),c[1580]||=n(`strong`,null,`Monica Geller:`,-1),c[1581]||=a(` I know! I’ll tell you something, we are gonna do that again!`,-1),c[1582]||=n(`blockquote`,null,[n(`p`,null,`我知道！我要告诉你一件事，我们要再做一次！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1632.936`,duration:`2.256`}),c[1583]||=a(),c[1584]||=n(`strong`,null,`Chandler Bing:`,-1),c[1585]||=a(` Oh, okay! (He rolls over to do that again.)`,-1),c[1586]||=n(`blockquote`,null,[n(`p`,null,`哦，好的！（他又翻了个身。）`)],-1),c[1587]||=n(`hr`,null,null,-1),c[1588]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Joey's apartment, the next morning, Rachel is passed out on the couch.`)],-1),c[1589]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`乔伊的公寓，第二天早上，瑞秋昏倒在沙发上。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1635.192`,duration:`1.56`}),c[1590]||=a(),c[1591]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1592]||=a(` (entering) Morning!`,-1),c[1593]||=n(`blockquote`,null,[n(`p`,null,`（进来）早上好！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1636.752`,duration:`1.656`}),c[1594]||=a(),c[1595]||=n(`strong`,null,`Rachel Green:`,-1),c[1596]||=a(` (wakes up suddenly and realizes where she is) Oh right.`,-1),c[1597]||=n(`blockquote`,null,[n(`p`,null,`（突然醒来，意识到她在哪里）哦，对了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1638.408`,duration:`1.488`}),c[1598]||=a(),c[1599]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1600]||=a(` Yeah.`,-1),c[1601]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1639.896`,duration:`5.136`}),c[1602]||=a(),c[1603]||=n(`strong`,null,`Rachel Green:`,-1),c[1604]||=a(` (groans) Oh God. Oh I can’t believe Joey Tribbiani heard me throw up!`,-1),c[1605]||=n(`blockquote`,null,[n(`p`,null,`（呻吟）哦，天哪。哦，我真不敢相信乔伊·特里比亚尼听到我吐了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1645.032`,duration:`3.096`}),c[1606]||=a(),c[1607]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1608]||=a(` Well he actually saw you a little bit too.`,-1),c[1609]||=n(`blockquote`,null,[n(`p`,null,`其实他也见过你一点。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1648.128`,duration:`4.944`}),c[1610]||=a(),c[1611]||=n(`strong`,null,`Rachel Green:`,-1),c[1612]||=a(` Noo! Oh God we did—we didn’t, we didn’t uhh…`,-1),c[1613]||=n(`blockquote`,null,[n(`p`,null,`不！哦，上帝，我们做到了我们没有，我们没有…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1653.072`,duration:`5.592`}),c[1614]||=a(),c[1615]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1616]||=a(` No! No! No, not after seeing that.`,-1),c[1617]||=n(`blockquote`,null,[n(`p`,null,`不！不不，看了以后就不会了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1658.664`,duration:`2.712`}),c[1618]||=a(),c[1619]||=n(`strong`,null,`Rachel Green:`,-1),c[1620]||=a(` God I’m just a horrible person.`,-1),c[1621]||=n(`blockquote`,null,[n(`p`,null,`天啊，我只是个可怕的人。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1661.376`,duration:`2.136`}),c[1622]||=a(),c[1623]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1624]||=a(` Wh-why?`,-1),c[1625]||=n(`blockquote`,null,[n(`p`,null,`为什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1663.512`,duration:`9.696`}),c[1626]||=a(),c[1627]||=n(`strong`,null,`Rachel Green:`,-1),c[1628]||=a(` Because I’m married. That’s right, I am a married woman! And I came to a TV star’s apartment to have an affair! Uck!`,-1),c[1629]||=n(`blockquote`,null,[n(`p`,null,`因为我结婚了。没错，我是个已婚女人！我到一个电视明星的公寓来谈恋爱！该死！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1673.208`,duration:`5.736`}),c[1630]||=a(),c[1631]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1632]||=a(` That’s ridiculous! I’m not a "Star," just a regular famous actor.`,-1),c[1633]||=n(`blockquote`,null,[n(`p`,null,`太可笑了！我不是明星，只是一个普通的著名演员。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1678.944`,duration:`3.456`}),c[1634]||=a(),c[1635]||=n(`strong`,null,`Rachel Green:`,-1),c[1636]||=a(` Yeah and I’m a horrible, horrible person.`,-1),c[1637]||=n(`blockquote`,null,[n(`p`,null,`是的，我是个可怕的人。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1682.4`,duration:`7.68`}),c[1638]||=a(),c[1639]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1640]||=a(` Rachel, would you stop saying that?! Hey-hey look, remember on the show when-when Caprice was dying and she gave me…`,-1),c[1641]||=n(`blockquote`,null,[n(`p`,null,`瑞秋，你能不能别再说了？！嘿，嘿，听着，还记得卡普瑞斯临死的时候，她给了我…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1690.08`,duration:`2.472`}),c[1642]||=a(),c[1643]||=n(`strong`,null,`Rachel Green:`,-1),c[1644]||=a(` The ring from the cave, yeah.`,-1),c[1645]||=n(`blockquote`,null,[n(`p`,null,`洞穴里的戒指，是的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1692.552`,duration:`3.912`}),c[1646]||=a(),c[1647]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1648]||=a(` Wow! Uh okay, well uh… (He gets up, opens a drawer, and pulls out the ring.)`,-1),c[1649]||=n(`blockquote`,null,[n(`p`,null,`哇！嗯，好吧，嗯…（他站起来，打开抽屉，拿出戒指。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1696.464`,duration:`3.24`}),c[1650]||=a(),c[1651]||=n(`strong`,null,`Rachel Green:`,-1),c[1652]||=a(` (seeing the ring and gasping) Oh my God, they let you keep that stuff?!`,-1),c[1653]||=n(`blockquote`,null,[n(`p`,null,`（看着戒指，喘着粗气）哦，天哪，他们让你保管那些东西？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1699.704`,duration:`7.536`}),c[1654]||=a(),c[1655]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1656]||=a(` Sure! As long as they don’t find out you can keep whatever you want! And I want you to have it.`,-1),c[1657]||=n(`blockquote`,null,[n(`p`,null,`当然！只要他们不发现，你可以保留你想要的任何东西！我希望你拥有它。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1707.24`,duration:`3.0`}),c[1658]||=a(),c[1659]||=n(`strong`,null,`Rachel Green:`,-1),c[1660]||=a(` No! No-no-no…`,-1),c[1661]||=n(`blockquote`,null,[n(`p`,null,`不！不，不，不…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1710.24`,duration:`14.808`}),c[1662]||=a(),c[1663]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1664]||=a(` Yes! Yes!! And every time you look at it, I want you to remember that you are a good person. Okay, you’ve had the chance to cheat, and with me, but you didn’t. And that’s what this ring stands for.`,-1),c[1665]||=n(`blockquote`,null,[n(`p`,null,`是的！对每次你看着它，我想让你记住你是一个好人。好吧，你有机会欺骗我，但你没有。这就是这枚戒指的意义。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1725.048`,duration:`4.416`}),c[1666]||=a(),c[1667]||=n(`strong`,null,`Rachel Green:`,-1),c[1668]||=a(` But I thought that ring stood for Caprice’s undying love for her brother.`,-1),c[1669]||=n(`blockquote`,null,[n(`p`,null,`但我以为那枚戒指代表着凯普瑞斯对她哥哥永恒的爱。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1729.464`,duration:`2.976`}),c[1670]||=a(),c[1671]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1672]||=a(` Look, do you want the ring or not?!`,-1),c[1673]||=n(`blockquote`,null,[n(`p`,null,`听着，你到底要不要戒指？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1732.44`,duration:`1.344`}),c[1674]||=a(),c[1675]||=n(`strong`,null,`Rachel Green:`,-1),c[1676]||=a(` Yeah!`,-1),c[1677]||=n(`blockquote`,null,[n(`p`,null,`是啊！`)],-1),c[1678]||=n(`hr`,null,null,-1),c[1679]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Phoebe’s hospital room, Joey and Ross enter as Phoebe comes out of the bathroom wearing her robe.`)],-1),c[1680]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`菲比穿着长袍走出浴室时，乔伊和罗斯进入菲比的病房。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1733.784`,duration:`1.44`}),c[1681]||=a(),c[1682]||=n(`strong`,null,`Ross Geller:`,-1),c[1683]||=a(` Hey!`,-1),c[1684]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1735.224`,duration:`1.488`}),c[1685]||=a(),c[1686]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1687]||=a(` Hey!`,-1),c[1688]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1736.712`,duration:`3.168`}),c[1689]||=a(),c[1690]||=n(`strong`,null,`Ross Geller:`,-1),c[1691]||=a(` Look at you! You’re up!`,-1),c[1692]||=n(`blockquote`,null,[n(`p`,null,`看看你！你起来了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1739.88`,duration:`1.656`}),c[1693]||=a(),c[1694]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1695]||=a(` All right!`,-1),c[1696]||=n(`blockquote`,null,[n(`p`,null,`好吧！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1741.536`,duration:`5.208`}),c[1697]||=a(),c[1698]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1699]||=a(` I thought I’d try to take a walk. Would you pour me some water? I’ll be back soon.`,-1),c[1700]||=n(`blockquote`,null,[n(`p`,null,`我想我应该试着去散散步。你能给我倒点水吗？我很快就回来。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1746.744`,duration:`5.64`}),c[1701]||=a(),c[1702]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1703]||=a(` Whoa-whoa-whoa! You’re not gonna use the pay phone to call work, are ya?`,-1),c[1704]||=n(`blockquote`,null,[n(`p`,null,`哇，哇，哇！你不会用付费电话给公司打电话吧？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1752.384`,duration:`2.304`}),c[1705]||=a(),c[1706]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1707]||=a(` No. I’ve learned my lesson.`,-1),c[1708]||=n(`blockquote`,null,[n(`p`,null,`不，我已经吸取了教训。`)],-1),c[1709]||=n(`p`,null,[n(`em`,null,`(She goes out into the hall and when she’s there and the door is closed; she rips off her robe to reveal her work clothes.)`)],-1),c[1710]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（她走出大厅，当她在那里时，门关上了；她撕掉长袍，露出她的工作服。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1754.688`,duration:`8.328`}),c[1711]||=a(),c[1712]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1713]||=a(` Let’s go! Come on! Move it! (Grabs her coat.) Come on! (To an old man who’s holding her shoes and briefcase.) Shoes! Briefcase! (Takes them both.) Thanks Lou, good luck with the gall bladder. (She leaves.)`,-1),c[1714]||=n(`blockquote`,null,[n(`p`,null,`我们走吧！来吧快点！（抓住她的外套）快点！（对拿着她的鞋子和公文包的老人）鞋子！公文包！（两个人都吃了。）谢谢卢，祝你胆囊好运。（她离开了。）`)],-1),c[1715]||=n(`p`,null,`[Cut back to her room, Joey and Ross are sitting there waiting for her.]`,-1),c[1716]||=n(`blockquote`,null,[n(`p`,null,`[回到她的房间，乔伊和罗斯坐在那里等她。]`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1763.016`,duration:`4.128`}),c[1717]||=a(),c[1718]||=n(`strong`,null,`Ross Geller:`,-1),c[1719]||=a(` Hey Joe did… Did you ever have a threesome?`,-1),c[1720]||=n(`blockquote`,null,[n(`p`,null,`嘿，乔……你有过三人行吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1767.144`,duration:`5.952`}),c[1721]||=a(),c[1722]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1723]||=a(` (not quite sure of how to answer that) Well uh, look Ross I uh, I think Carol’s great and I’m sure you’re a very attractive man, but I….`,-1),c[1724]||=n(`blockquote`,null,[n(`p`,null,`（不太清楚该怎么回答）嗯，罗斯，我，呃，我觉得卡萝很棒，我相信你是个很有魅力的男人，但是我…。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1773.096`,duration:`6.576`}),c[1725]||=a(),c[1726]||=n(`strong`,null,`Ross Geller:`,-1),c[1727]||=a(` No! The reason I’m asking is that… I sorta had one last night.`,-1),c[1728]||=n(`blockquote`,null,[n(`p`,null,`不！我问的原因是…我昨晚喝了一杯。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1779.672`,duration:`1.464`}),c[1729]||=a(),c[1730]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1731]||=a(` You?`,-1),c[1732]||=n(`blockquote`,null,[n(`p`,null,`你呢？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1781.136`,duration:`1.416`}),c[1733]||=a(),c[1734]||=n(`strong`,null,`Ross Geller:`,-1),c[1735]||=a(` Yeah!`,-1),c[1736]||=n(`blockquote`,null,[n(`p`,null,`是啊！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1782.552`,duration:`1.512`}),c[1737]||=a(),c[1738]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1739]||=a(` Wow!`,-1),c[1740]||=n(`blockquote`,null,[n(`p`,null,`哇！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1784.064`,duration:`1.416`}),c[1741]||=a(),c[1742]||=n(`strong`,null,`Ross Geller:`,-1),c[1743]||=a(` Yeah!`,-1),c[1744]||=n(`blockquote`,null,[n(`p`,null,`是啊！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1785.48`,duration:`3.984`}),c[1745]||=a(),c[1746]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1747]||=a(` All right! So, was it amazing?`,-1),c[1748]||=n(`blockquote`,null,[n(`p`,null,`好吧！那么，是不是很神奇？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1789.464`,duration:`2.784`}),c[1749]||=a(),c[1750]||=n(`strong`,null,`Ross Geller:`,-1),c[1751]||=a(` It was, it was okay.`,-1),c[1752]||=n(`blockquote`,null,[n(`p`,null,`是的，没关系。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1792.248`,duration:`2.784`}),c[1753]||=a(),c[1754]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1755]||=a(` Just okay—Did you do it right?!`,-1),c[1756]||=n(`blockquote`,null,[n(`p`,null,`还好，你做对了吗？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1795.032`,duration:`6.768`}),c[1757]||=a(),c[1758]||=n(`strong`,null,`Ross Geller:`,-1),c[1759]||=a(` Look, it’s just did, did you ever go to a party and think, "Would really anyone miss me if I weren’t here?"`,-1),c[1760]||=n(`blockquote`,null,[n(`p`,null,`听着，就是这样，你有没有去参加一个聚会，然后想，“如果我不在这里，真的会有人想念我吗？”`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1801.8`,duration:`8.64`}),c[1761]||=a(),c[1762]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1763]||=a(` Huh. But still Ross, you’re worst day with two women, pretty much better than any other day! Y’know what I mean?`,-1),c[1764]||=n(`blockquote`,null,[n(`p`,null,`嗯。但罗斯，你和两个女人在一起是最糟糕的一天，比任何一天都要好！你知道我的意思吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1810.44`,duration:`2.496`}),c[1765]||=a(),c[1766]||=n(`strong`,null,`Ross Geller:`,-1),c[1767]||=a(` Oh-oh, absolutely!`,-1),c[1768]||=n(`blockquote`,null,[n(`p`,null,`哦，当然！`)],-1),c[1769]||=n(`p`,null,[n(`em`,null,`(They both laugh.)`)],-1),c[1770]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（他们都笑了。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1812.936`,duration:`6.552`}),c[1771]||=a(),c[1772]||=n(`strong`,null,`Ross Geller:`,-1),c[1773]||=a(` It’s just, my part seemed to be over pretty quickly and then, and then there was a lot of waiting around.`,-1),c[1774]||=n(`blockquote`,null,[n(`p`,null,`只是，我的角色似乎很快就结束了，然后有很多人在等着。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1819.488`,duration:`3.144`}),c[1775]||=a(),c[1776]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1777]||=a(` But you got to be with both of them, right?`,-1),c[1778]||=n(`blockquote`,null,[n(`p`,null,`但是你必须和他们两个在一起，对吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1822.632`,duration:`4.824`}),c[1779]||=a(),c[1780]||=n(`strong`,null,`Ross Geller:`,-1),c[1781]||=a(` Not-not really. Th-th-there was just Carol.`,-1),c[1782]||=n(`blockquote`,null,[n(`p`,null,`不是真的。只有卡萝。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1827.456`,duration:`2.016`}),c[1783]||=a(),c[1784]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1785]||=a(` Not the other one?`,-1),c[1786]||=n(`blockquote`,null,[n(`p`,null,`不是另一个吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1829.472`,duration:`3.144`}),c[1787]||=a(),c[1788]||=n(`strong`,null,`Ross Geller:`,-1),c[1789]||=a(` No, she kept kicking me away!`,-1),c[1790]||=n(`blockquote`,null,[n(`p`,null,`不，她一直把我踢开！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1832.616`,duration:`2.4`}),c[1791]||=a(),c[1792]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1793]||=a(` Yeah, you don’t want that.`,-1),c[1794]||=n(`blockquote`,null,[n(`p`,null,`是的，你不会想要的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1835.016`,duration:`1.488`}),c[1795]||=a(),c[1796]||=n(`strong`,null,`Ross Geller:`,-1),c[1797]||=a(` No!`,-1),c[1798]||=n(`blockquote`,null,[n(`p`,null,`不！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1836.504`,duration:`3.912`}),c[1799]||=a(),c[1800]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1801]||=a(` Well hey, at least you got to see a lot of stuff, right?`,-1),c[1802]||=n(`blockquote`,null,[n(`p`,null,`嘿，至少你看到了很多东西，对吧？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1840.416`,duration:`2.496`}),c[1803]||=a(),c[1804]||=n(`strong`,null,`Ross Geller:`,-1),c[1805]||=a(` Oh I a lot of stuff!`,-1),c[1806]||=n(`blockquote`,null,[n(`p`,null,`哦，我有很多东西！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1842.912`,duration:`2.256`}),c[1807]||=a(),c[1808]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1809]||=a(` You got a little bored?`,-1),c[1810]||=n(`blockquote`,null,[n(`p`,null,`你有点无聊吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1845.168`,duration:`4.704`}),c[1811]||=a(),c[1812]||=n(`strong`,null,`Ross Geller:`,-1),c[1813]||=a(` A little. Yeah. I made a snack.`,-1),c[1814]||=n(`blockquote`,null,[n(`p`,null,`有点。是 啊我做了一份点心。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1849.872`,duration:`3.432`}),c[1815]||=a(),c[1816]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1817]||=a(` Yeah? What did ya have?`,-1),c[1818]||=n(`blockquote`,null,[n(`p`,null,`是吗？你吃了什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1853.304`,duration:`4.584`}),c[1819]||=a(),c[1820]||=n(`strong`,null,`Ross Geller:`,-1),c[1821]||=a(` Just a sandwich. Turkey, a little mustard…`,-1),c[1822]||=n(`blockquote`,null,[n(`p`,null,`就一个三明治。火鸡，一点芥末…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1857.888`,duration:`1.92`}),c[1823]||=a(),c[1824]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[1825]||=a(` Sounds good.`,-1),c[1826]||=n(`blockquote`,null,[n(`p`,null,`听起来不错。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1859.808`,duration:`2.088`}),c[1827]||=a(),c[1828]||=n(`strong`,null,`Ross Geller:`,-1),c[1829]||=a(` It really was!`,-1),c[1830]||=n(`blockquote`,null,[n(`p`,null,`真的！`)],-1),c[1831]||=n(`hr`,null,null,-1),c[1832]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Phoebe's, Monica is making a sandwich as Chandler enters.`)],-1),c[1833]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和菲比家，钱德勒进来时莫妮卡正在做三明治。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1861.896`,duration:`1.44`}),c[1834]||=a(),c[1835]||=n(`strong`,null,`Chandler Bing:`,-1),c[1836]||=a(` Hey!`,-1),c[1837]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1863.336`,duration:`1.488`}),c[1838]||=a(),c[1839]||=n(`strong`,null,`Monica Geller:`,-1),c[1840]||=a(` Hey!`,-1),c[1841]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1864.824`,duration:`6.432`}),c[1842]||=a(),c[1843]||=n(`strong`,null,`Chandler Bing:`,-1),c[1844]||=a(` Let me tell you about this chick I scored with last night! Oh no wait a minute that was you!`,-1),c[1845]||=n(`blockquote`,null,[n(`p`,null,`让我告诉你昨晚和我一起得分的那个女孩！哦，不，等等，那是你！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1871.256`,duration:`3.072`}),c[1846]||=a(),c[1847]||=n(`strong`,null,`Monica Geller:`,-1),c[1848]||=a(` Hey, check me out, I’m a slut!`,-1),c[1849]||=n(`blockquote`,null,[n(`p`,null,`嘿，看看我，我是个荡妇！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1874.328`,duration:`3.408`}),c[1850]||=a(),c[1851]||=n(`strong`,null,`Chandler Bing:`,-1),c[1852]||=a(` So you uh, want to do something tonight?`,-1),c[1853]||=n(`blockquote`,null,[n(`p`,null,`那么你今晚想做点什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1877.736`,duration:`4.776`}),c[1854]||=a(),c[1855]||=n(`strong`,null,`Monica Geller:`,-1),c[1856]||=a(` Oh I can’t. Dr. Roger is coming over again.`,-1),c[1857]||=n(`blockquote`,null,[n(`p`,null,`哦，我不能。罗杰医生又来了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1882.512`,duration:`11.328`}),c[1858]||=a(),c[1859]||=n(`strong`,null,`Chandler Bing:`,-1),c[1860]||=a(` Oh. Oh right! Right! Because you’re still seeing him and uh, he’s a good guy. I mean, I remember a time when… (He fakes falling asleep.)`,-1),c[1861]||=n(`blockquote`,null,[n(`p`,null,`哦。哦，对了！正确的！因为你还在看他，而且他是个好人。我是说，我记得有一次…（他假装睡着了。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1893.84`,duration:`1.824`}),c[1862]||=a(),c[1863]||=n(`strong`,null,`Monica Geller:`,-1),c[1864]||=a(` Are you okay?`,-1),c[1865]||=n(`blockquote`,null,[n(`p`,null,`你没事吧？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1895.664`,duration:`5.064`}),c[1866]||=a(),c[1867]||=n(`strong`,null,`Chandler Bing:`,-1),c[1868]||=a(` Yeah! Totally! Totally, and you?`,-1),c[1869]||=n(`blockquote`,null,[n(`p`,null,`是啊！完全地完全正确，你呢？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1900.728`,duration:`11.712`}),c[1870]||=a(),c[1871]||=n(`strong`,null,`Monica Geller:`,-1),c[1872]||=a(` Great! It’s so amazing! I mean, last time Dr. Roger came over, I was so nervous, but then after being with you I’m all like, "Can the doctor see me now?"`,-1),c[1873]||=n(`blockquote`,null,[n(`p`,null,`太好了！太神奇了！我是说，上次罗杰医生来的时候，我很紧张，但和你在一起之后，我就想，“医生现在能看我吗？”`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1912.44`,duration:`1.992`}),c[1874]||=a(),c[1875]||=n(`strong`,null,`Chandler Bing:`,-1),c[1876]||=a(` I bet he can.`,-1),c[1877]||=n(`blockquote`,null,[n(`p`,null,`我打赌他能。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1914.432`,duration:`6.744`}),c[1878]||=a(),c[1879]||=n(`strong`,null,`Monica Geller:`,-1),c[1880]||=a(` Y’know, I don’t have an appointment, but I sure could use a physical. (He laughs halfheartedly) Are you sure you’re okay?`,-1),c[1881]||=n(`blockquote`,null,[n(`p`,null,`你知道，我没有预约，但我肯定需要体检。（他半心半意地笑）你确定你没事吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1921.176`,duration:`5.928`}),c[1882]||=a(),c[1883]||=n(`strong`,null,`Chandler Bing:`,-1),c[1884]||=a(` Oh yeah! Yeah! Don’t worry about me, I’ll be fine! (Does a kara-tay move.)`,-1),c[1885]||=n(`blockquote`,null,[n(`p`,null,`哦，是的！是 啊别担心我，我会没事的！（卡拉·泰会移动。）`)],-1),c[1886]||=n(`hr`,null,null,-1),c[1887]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Rachel and Barry’s bedroom, Rachel is returning from her disastrous attempt at an affair to find that Barry was much, much more successful with his.`)],-1),c[1888]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`瑞秋和巴里的卧室，瑞秋正从一场灾难性的风流韵事中归来，发现巴里的婚姻更加成功。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1927.104`,duration:`4.296`}),c[1889]||=a(),c[1890]||=n(`strong`,null,`Rachel Green:`,-1),c[1891]||=a(` Ohh! My God! Barry!!`,-1),c[1892]||=n(`blockquote`,null,[n(`p`,null,`哦！天哪！巴里！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1931.4`,duration:`2.88`}),c[1893]||=a(),c[1894]||=n(`strong`,null,`Barry:`,-1),c[1895]||=a(` You-you-you said you were gonna be away all weekend!`,-1),c[1896]||=n(`blockquote`,null,[n(`p`,null,`你说你整个周末都不在！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1934.28`,duration:`8.256`}),c[1897]||=a(),c[1898]||=n(`strong`,null,`Rachel Green:`,-1),c[1899]||=a(` Oh that’s right! I’m sorry! I-I am early! Finish! Please!!`,-1),c[1900]||=n(`blockquote`,null,[n(`p`,null,`哦，对了！我很抱歉！我来早了！结束！请`)],-1),c[1901]||=n(`hr`,null,null,-1),c[1902]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Phoebe’s office, she is arriving without the knowledge that she’s been fired.`)],-1),c[1903]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`菲比的办公室，她在不知道自己被解雇的情况下到达。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1942.536`,duration:`2.52`}),c[1904]||=a(),c[1905]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1906]||=a(` Surprise! Look who’s back!`,-1),c[1907]||=n(`blockquote`,null,[n(`p`,null,`惊喜！看谁回来了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1945.056`,duration:`1.32`}),c[1908]||=a(),c[1909]||=n(`strong`,null,`Arthur:`,-1),c[1910]||=a(` Hey Pheebs!`,-1),c[1911]||=n(`blockquote`,null,[n(`p`,null,`嘿，菲比！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1946.376`,duration:`0.816`}),c[1912]||=a(),c[1913]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1914]||=a(` Hey!`,-1),c[1915]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1947.192`,duration:`3.192`}),c[1916]||=a(),c[1917]||=n(`strong`,null,`Arthur:`,-1),c[1918]||=a(` (To another coworker) Call security. (To Phoebe) Pheebs, didn’t you get fired?`,-1),c[1919]||=n(`blockquote`,null,[n(`p`,null,`（对另一位同事）打电话给保安。（对菲比）菲比，你不是被解雇了吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1950.384`,duration:`1.536`}),c[1920]||=a(),c[1921]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1922]||=a(` Uh, I don’t think so!`,-1),c[1923]||=n(`blockquote`,null,[n(`p`,null,`嗯，我不这么认为！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1951.92`,duration:`0.912`}),c[1924]||=a(),c[1925]||=n(`strong`,null,`Jack:`,-1),c[1926]||=a(` Phoebe?`,-1),c[1927]||=n(`blockquote`,null,[n(`p`,null,`菲比？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1952.832`,duration:`1.752`}),c[1928]||=a(),c[1929]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1930]||=a(` Jack!! Hey!`,-1),c[1931]||=n(`blockquote`,null,[n(`p`,null,`杰克！！嘿`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1954.584`,duration:`1.32`}),c[1932]||=a(),c[1933]||=n(`strong`,null,`Jack:`,-1),c[1934]||=a(` What are you doing here?`,-1),c[1935]||=n(`blockquote`,null,[n(`p`,null,`你在这里干什么？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1955.904`,duration:`7.416`}),c[1936]||=a(),c[1937]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1938]||=a(` All better! Back to work! Except this clown from research told me I was fired. He should do his research, huh?`,-1),c[1939]||=n(`blockquote`,null,[n(`p`,null,`好多了！回去工作！除了一个研究所的小丑告诉我我被解雇了。他应该做他的研究，嗯？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1963.32`,duration:`1.248`}),c[1940]||=a(),c[1941]||=n(`strong`,null,`Jack:`,-1),c[1942]||=a(` Well, you were fired.`,-1),c[1943]||=n(`blockquote`,null,[n(`p`,null,`嗯，你被解雇了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1964.568`,duration:`0.84`}),c[1944]||=a(),c[1945]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1946]||=a(` Nu-uh!`,-1),c[1947]||=n(`blockquote`,null,[n(`p`,null,`努恩！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1965.408`,duration:`2.016`}),c[1948]||=a(),c[1949]||=n(`strong`,null,`Jack:`,-1),c[1950]||=a(` I told that guy who answered your phone.`,-1),c[1951]||=n(`blockquote`,null,[n(`p`,null,`我告诉了那个接你电话的人。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1967.424`,duration:`5.736`}),c[1952]||=a(),c[1953]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1954]||=a(` Oh, okay I didn’t get that message. So this doesn’t count—Anyway, I’ll be in my office.`,-1),c[1955]||=n(`blockquote`,null,[n(`p`,null,`哦，好吧，我没有收到那个信息。所以这不算数，我会在办公室。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1973.16`,duration:`2.952`}),c[1956]||=a(),c[1957]||=n(`strong`,null,`Jack:`,-1),c[1958]||=a(` Uh, Phoebe you-you don’t have an office.`,-1),c[1959]||=n(`blockquote`,null,[n(`p`,null,`嗯，菲比，你没有办公室。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1976.112`,duration:`4.128`}),c[1960]||=a(),c[1961]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1962]||=a(` That’s all right, I’ll work here. This is goo, next to this plant. (She picks a place in the lobby next to a plant.)`,-1),c[1963]||=n(`blockquote`,null,[n(`p`,null,`没关系，我在这里工作。这是古，在这家工厂旁边。（她在大厅里选了一个靠近植物的地方。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1980.24`,duration:`1.176`}),c[1964]||=a(),c[1965]||=n(`strong`,null,`Jack:`,-1),c[1966]||=a(` (approaches her) Phoebe, listen…`,-1),c[1967]||=n(`blockquote`,null,[n(`p`,null,`（走近她）菲比，听着…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1981.416`,duration:`11.52`}),c[1968]||=a(),c[1969]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1970]||=a(` You’re in my office! Look, I have made a lot of cash for this company! Okay? I am talking big bucks! Pesos! Yen! Rubles! You make one little mistake…`,-1),c[1971]||=n(`blockquote`,null,[n(`p`,null,`你在我的办公室！瞧，我为这家公司赚了很多钱！可以我说的是大钱！比索！日元卢布！你犯了一个小错误…`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1992.936`,duration:`2.424`}),c[1972]||=a(),c[1973]||=n(`strong`,null,`Jack:`,-1),c[1974]||=a(` You lost 13 million dollars.`,-1),c[1975]||=n(`blockquote`,null,[n(`p`,null,`你损失了1300万美元。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`1995.36`,duration:`5.928`}),c[1976]||=a(),c[1977]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1978]||=a(` Oh, so this is all about money! Y’know it’s bad enough that—Ow! Oh, you have got to be kidding!`,-1),c[1979]||=n(`blockquote`,null,[n(`p`,null,`哦，这都是钱的问题！你知道这已经够糟糕的了！哦，你一定是在开玩笑！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2001.288`,duration:`1.104`}),c[1980]||=a(),c[1981]||=n(`strong`,null,`Jack:`,-1),c[1982]||=a(` Are you all right?`,-1),c[1983]||=n(`blockquote`,null,[n(`p`,null,`你没事吧？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2002.392`,duration:`2.184`}),c[1984]||=a(),c[1985]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1986]||=a(` I’m having another heart attack!`,-1),c[1987]||=n(`blockquote`,null,[n(`p`,null,`我又心脏病发作了！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2004.576`,duration:`0.696`}),c[1988]||=a(),c[1989]||=n(`strong`,null,`Jack:`,-1),c[1990]||=a(` What?!`,-1),c[1991]||=n(`blockquote`,null,[n(`p`,null,`什么？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2005.272`,duration:`3.888`}),c[1992]||=a(),c[1993]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[1994]||=a(` I’m having another heart attack!! Call 9-1-1!!`,-1),c[1995]||=n(`blockquote`,null,[n(`p`,null,`我又心脏病发作了！！打911！！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2009.16`,duration:`1.104`}),c[1996]||=a(),c[1997]||=n(`strong`,null,`Jack:`,-1),c[1998]||=a(` Take it easy. (Sits her down.)`,-1),c[1999]||=n(`blockquote`,null,[n(`p`,null,`别紧张。（让她坐下。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2010.264`,duration:`0.984`}),c[2e3]||=a(),c[2001]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[2002]||=a(` (to Arthur, he’s the guy calling 9-1-1) Dumbass!`,-1),c[2003]||=n(`blockquote`,null,[n(`p`,null,`（对亚瑟说，他就是那个叫9-1-1）笨蛋的家伙！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2011.248`,duration:`2.352`}),c[2004]||=a(),c[2005]||=n(`strong`,null,`Woman:`,-1),c[2006]||=a(` Hey Pheebs! How’s it going?!`,-1),c[2007]||=n(`blockquote`,null,[n(`p`,null,`嘿，菲比！怎么样？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2013.6`,duration:`2.712`}),c[2008]||=a(),c[2009]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[2010]||=a(` Well, they fired me and I’m having heart attack.`,-1),c[2011]||=n(`blockquote`,null,[n(`p`,null,`嗯，他们解雇了我，我心脏病发作了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2016.312`,duration:`1.992`}),c[2012]||=a(),c[2013]||=n(`strong`,null,`Woman:`,-1),c[2014]||=a(` Wow! Well, welcome back!`,-1),c[2015]||=n(`blockquote`,null,[n(`p`,null,`哇！欢迎回来！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2018.304`,duration:`0.6`}),c[2016]||=a(),c[2017]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[2018]||=a(` Yeah.`,-1),c[2019]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),c[2020]||=n(`hr`,null,null,-1),c[2021]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Central Perk, Ross is there as Rachel storms in.`)],-1),c[2022]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`中央公园，瑞秋冲进时罗斯在那里。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2018.904`,duration:`1.752`}),c[2023]||=a(),c[2024]||=n(`strong`,null,`Rachel Green:`,-1),c[2025]||=a(` Hi Ross!`,-1),c[2026]||=n(`blockquote`,null,[n(`p`,null,`嗨，罗斯！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2020.656`,duration:`1.8`}),c[2027]||=a(),c[2028]||=n(`strong`,null,`Ross Geller:`,-1),c[2029]||=a(` Hey Rachel.`,-1),c[2030]||=n(`blockquote`,null,[n(`p`,null,`嘿，瑞秋。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2022.456`,duration:`2.304`}),c[2031]||=a(),c[2032]||=n(`strong`,null,`Rachel Green:`,-1),c[2033]||=a(` Is Joey Tribbiani here?`,-1),c[2034]||=n(`blockquote`,null,[n(`p`,null,`乔伊·特里比亚尼在吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2024.76`,duration:`2.016`}),c[2035]||=a(),c[2036]||=n(`strong`,null,`Ross Geller:`,-1),c[2037]||=a(` Umm, no.`,-1),c[2038]||=n(`blockquote`,null,[n(`p`,null,`嗯，没有。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2026.776`,duration:`6.024`}),c[2039]||=a(),c[2040]||=n(`strong`,null,`Rachel Green:`,-1),c[2041]||=a(` Well, if you see him, will you please tell him that I’m looking for him and that this I am not gonna throw up!`,-1),c[2042]||=n(`blockquote`,null,[n(`p`,null,`如果你看到他，请你告诉他我在找他，我不会吐的！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2032.8`,duration:`4.272`}),c[2043]||=a(),c[2044]||=n(`strong`,null,`Ross Geller:`,-1),c[2045]||=a(` That-that’s always good news. Are you okay?`,-1),c[2046]||=n(`blockquote`,null,[n(`p`,null,`那总是好消息。你没事吧？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2037.072`,duration:`12.288`}),c[2047]||=a(),c[2048]||=n(`strong`,null,`Rachel Green:`,-1),c[2049]||=a(` Me? I’m great! I’m fine! I’m sooo good!! But, you know who’s not great?! Men! You’re a man right Ross?!`,-1),c[2050]||=n(`blockquote`,null,[n(`p`,null,`我？我很好！我很好！我很好！！但是，你知道谁不伟大吗？！男人们！你是个男人，对吧，罗斯？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2049.36`,duration:`1.368`}),c[2051]||=a(),c[2052]||=n(`strong`,null,`Ross Geller:`,-1),c[2053]||=a(` Yeah.`,-1),c[2054]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2050.728`,duration:`1.752`}),c[2055]||=a(),c[2056]||=n(`strong`,null,`Rachel Green:`,-1),c[2057]||=a(` Sit down!`,-1),c[2058]||=n(`blockquote`,null,[n(`p`,null,`坐下！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2052.48`,duration:`1.512`}),c[2059]||=a(),c[2060]||=n(`strong`,null,`Ross Geller:`,-1),c[2061]||=a(` Okay. (He does so.)`,-1),c[2062]||=n(`blockquote`,null,[n(`p`,null,`好的。（他这样做了。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2053.992`,duration:`11.496`}),c[2063]||=a(),c[2064]||=n(`strong`,null,`Rachel Green:`,-1),c[2065]||=a(` Let me uh, let me ask you something, do wedding vows mean squat to you people?! And why is it that the second we tell you we’re going out of town, bamn there you are in bed with the neighbor’s dog walker?!`,-1),c[2066]||=n(`blockquote`,null,[n(`p`,null,`让我，呃，让我问你一件事，结婚誓言对你们来说意味着蹲下吗？！为什么我们告诉你我们要出城的那一刻，你就和邻居的遛狗人上床了？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2065.488`,duration:`1.752`}),c[2067]||=a(),c[2068]||=n(`strong`,null,`Ross Geller:`,-1),c[2069]||=a(` We’re sorry.`,-1),c[2070]||=n(`blockquote`,null,[n(`p`,null,`我们很抱歉。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2067.24`,duration:`6.768`}),c[2071]||=a(),c[2072]||=n(`strong`,null,`Rachel Green:`,-1),c[2073]||=a(` No seriously! Seriously! What has happened to the sanctity of marriage?`,-1),c[2074]||=n(`blockquote`,null,[n(`p`,null,`不，说真的！认真地婚姻的神圣性怎么了？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2074.008`,duration:`2.784`}),c[2075]||=a(),c[2076]||=n(`strong`,null,`Ross Geller:`,-1),c[2077]||=a(` Didn’t you spend last night at Joey’s?`,-1),c[2078]||=n(`blockquote`,null,[n(`p`,null,`你昨晚不是在乔伊家度过的吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2076.792`,duration:`3.456`}),c[2079]||=a(),c[2080]||=n(`strong`,null,`Rachel Green:`,-1),c[2081]||=a(` Aw what are you?! A detective?`,-1),c[2082]||=n(`blockquote`,null,[n(`p`,null,`哦，你是什么？！侦探？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2080.248`,duration:`8.376`}),c[2083]||=a(),c[2084]||=n(`strong`,null,`Ross Geller:`,-1),c[2085]||=a(` Look I-I don’t know what’s going on with you and your husband and what is hopefully an adult dog walker, look can I just say not all men are like that.`,-1),c[2086]||=n(`blockquote`,null,[n(`p`,null,`听着，我不知道你和你丈夫怎么了，也不知道什么是一个成年遛狗者，听着，我可以说不是所有的男人都是这样的。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2088.624`,duration:`1.44`}),c[2087]||=a(),c[2088]||=n(`strong`,null,`Rachel Green:`,-1),c[2089]||=a(` Oh. (Doesn’t believe it.)`,-1),c[2090]||=n(`blockquote`,null,[n(`p`,null,`哦。（我不相信。）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2090.064`,duration:`16.224`}),c[2091]||=a(),c[2092]||=n(`strong`,null,`Ross Geller:`,-1),c[2093]||=a(` Hey! There are some men who will do whatever it takes to make their marriage work! Okay? There are some men who will stand by and-and watch as their wives engage in-in what only can be described as a twosome with some-some woman she barely knows from the gym!`,-1),c[2094]||=n(`blockquote`,null,[n(`p`,null,`嘿！有些男人会不惜一切代价来维持他们的婚姻！可以有些男人会袖手旁观，看着他们的妻子和一个她在健身房里几乎不认识的女人进行一场所谓的双人赛！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2106.288`,duration:`1.944`}),c[2095]||=a(),c[2096]||=n(`strong`,null,`Rachel Green:`,-1),c[2097]||=a(` Who are these men?`,-1),c[2098]||=n(`blockquote`,null,[n(`p`,null,`这些人是谁？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2108.232`,duration:`3.432`}),c[2099]||=a(),c[2100]||=n(`strong`,null,`Ross Geller:`,-1),c[2101]||=a(` Men. I guy I know.`,-1),c[2102]||=n(`blockquote`,null,[n(`p`,null,`男人。我认识一个人。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2111.664`,duration:`3.936`}),c[2103]||=a(),c[2104]||=n(`strong`,null,`Rachel Green:`,-1),c[2105]||=a(` Well, you might want to tell him it sounds like his wife is (whispers) gay.`,-1),c[2106]||=n(`blockquote`,null,[n(`p`,null,`嗯，你可能想告诉他，听起来他妻子是同性恋。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2115.6`,duration:`9.408`}),c[2107]||=a(),c[2108]||=n(`strong`,null,`Ross Geller:`,-1),c[2109]||=a(` She is not… (Realizes) She’s gay. Oh my God. She is so gay! I can’t believe this.`,-1),c[2110]||=n(`blockquote`,null,[n(`p`,null,`她不是…（意识到）她是同性恋。哦，我的上帝。她真是个同性恋！真不敢相信。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2125.008`,duration:`2.424`}),c[2111]||=a(),c[2112]||=n(`strong`,null,`Rachel Green:`,-1),c[2113]||=a(` Good day for married people huh?`,-1),c[2114]||=n(`blockquote`,null,[n(`p`,null,`结婚的好日子啊？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2127.432`,duration:`2.976`}),c[2115]||=a(),c[2116]||=n(`strong`,null,`Ross Geller:`,-1),c[2117]||=a(` I’m sorry your husband cheated on you.`,-1),c[2118]||=n(`blockquote`,null,[n(`p`,null,`我很抱歉你丈夫背叛了你。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2130.408`,duration:`5.16`}),c[2119]||=a(),c[2120]||=n(`strong`,null,`Rachel Green:`,-1),c[2121]||=a(` I’m sorry your wife is gay. I guess women aren’t that great either.`,-1),c[2122]||=n(`blockquote`,null,[n(`p`,null,`很抱歉你妻子是同性恋。我猜女人也没那么好。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2135.568`,duration:`2.496`}),c[2123]||=a(),c[2124]||=n(`strong`,null,`Ross Geller:`,-1),c[2125]||=a(` Try telling my wife that.`,-1),c[2126]||=n(`blockquote`,null,[n(`p`,null,`试着告诉我妻子。`)],-1),c[2127]||=n(`hr`,null,null,-1),c[2128]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Phoebe's, Monica is blowing out a candle as Chandler enters.`)],-1),c[2129]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和菲比家，钱德勒进来时莫妮卡正在吹灭蜡烛。`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2138.064`,duration:`1.992`}),c[2130]||=a(),c[2131]||=n(`strong`,null,`Chandler Bing:`,-1),c[2132]||=a(` (sticking his head in the door) Okay to come in?`,-1),c[2133]||=n(`blockquote`,null,[n(`p`,null,`（把头伸进门）可以进来吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2140.056`,duration:`6.216`}),c[2134]||=a(),c[2135]||=n(`strong`,null,`Monica Geller:`,-1),c[2136]||=a(` Yeah, come on, eat, whatever you want. Dr. Roger got beeped again.`,-1),c[2137]||=n(`blockquote`,null,[n(`p`,null,`是啊，来吧，想吃什么就吃什么。罗杰医生又被传呼了。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2146.272`,duration:`2.856`}),c[2138]||=a(),c[2139]||=n(`strong`,null,`Chandler Bing:`,-1),c[2140]||=a(` Yeah I know, guess who beeped him?`,-1),c[2141]||=n(`blockquote`,null,[n(`p`,null,`是的，我知道，猜猜是谁呼他的？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2149.128`,duration:`1.464`}),c[2142]||=a(),c[2143]||=n(`strong`,null,`Monica Geller:`,-1),c[2144]||=a(` What?!`,-1),c[2145]||=n(`blockquote`,null,[n(`p`,null,`什么？！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2150.592`,duration:`2.304`}),c[2146]||=a(),c[2147]||=n(`strong`,null,`Chandler Bing:`,-1),c[2148]||=a(` I’m the ruptured spleen. (Laughs.)`,-1),c[2149]||=n(`blockquote`,null,[n(`p`,null,`我是脾脏破裂的人。（笑）`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2152.896`,duration:`2.112`}),c[2150]||=a(),c[2151]||=n(`strong`,null,`Monica Geller:`,-1),c[2152]||=a(` Why would you do that?`,-1),c[2153]||=n(`blockquote`,null,[n(`p`,null,`你为什么要这么做？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2155.008`,duration:`4.344`}),c[2154]||=a(),c[2155]||=n(`strong`,null,`Chandler Bing:`,-1),c[2156]||=a(` Because you shouldn’t be with him. (Pause.) You should be with me.`,-1),c[2157]||=n(`blockquote`,null,[n(`p`,null,`因为你不应该和他在一起。（停顿）你应该和我在一起。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2159.352`,duration:`1.512`}),c[2158]||=a(),c[2159]||=n(`strong`,null,`Monica Geller:`,-1),c[2160]||=a(` Really?`,-1),c[2161]||=n(`blockquote`,null,[n(`p`,null,`真的吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2160.864`,duration:`21.768`}),c[2162]||=a(),c[2163]||=n(`strong`,null,`Chandler Bing:`,-1),c[2164]||=a(` Yeah! When you were talking about Roger, that was killing me! Look, things like last night they don’t just happen. Y’know? Or at least not to me. Or with the other two women, in the morning y’know I was just lying there and I couldn’t wait to just go hang out with my friends, but with you I always y’know with a friend.`,-1),c[2165]||=n(`blockquote`,null,[n(`p`,null,`是啊！当你说罗杰的时候，我真是快死了！听着，像昨晚这样的事情不是偶然发生的。你知道吗？至少对我来说不是。或者和另外两个女人，早上你知道我只是躺在那里，我迫不及待地想和我的朋友出去玩，但和你在一起我总是和朋友在一起。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2182.632`,duration:`1.656`}),c[2166]||=a(),c[2167]||=n(`strong`,null,`Monica Geller:`,-1),c[2168]||=a(` Chandler!`,-1),c[2169]||=n(`blockquote`,null,[n(`p`,null,`钱德勒！`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2184.288`,duration:`9.456`}),c[2170]||=a(),c[2171]||=n(`strong`,null,`Chandler Bing:`,-1),c[2172]||=a(` I know you probably don’t want to go out with me, y’know because I make too many jokes and I’ve never been in a serious relationship and I guess I’m not technically a "doctor…"`,-1),c[2173]||=n(`blockquote`,null,[n(`p`,null,`我知道你可能不想和我出去，你知道，因为我开了太多玩笑，而且我从来没有认真地谈过恋爱，而且我猜严格来说我不是一个“医生…”`)],-1),c[2174]||=n(`p`,null,[n(`em`,null,`(Monica runs over and kisses him.)`)],-1),c[2175]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（莫妮卡跑过去吻他。）`)])],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2193.744`,duration:`3.072`}),c[2176]||=a(),c[2177]||=n(`strong`,null,`Monica Geller:`,-1),c[2178]||=a(` There was just one woman, wasn’t there?`,-1),c[2179]||=n(`blockquote`,null,[n(`p`,null,`只有一个女人，不是吗？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2196.816`,duration:`2.4`}),c[2180]||=a(),c[2181]||=n(`strong`,null,`Chandler Bing:`,-1),c[2182]||=a(` No, there were two.`,-1),c[2183]||=n(`blockquote`,null,[n(`p`,null,`不，有两个。`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2199.216`,duration:`1.8`}),c[2184]||=a(),c[2185]||=n(`strong`,null,`Monica Geller:`,-1),c[2186]||=a(` Including me?`,-1),c[2187]||=n(`blockquote`,null,[n(`p`,null,`包括我？`)],-1),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2201.016`,duration:`1.632`}),c[2188]||=o(` <strong>Chandler Bing:</strong> Oh yeah.<blockquote><p>哦，是的。</p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Central Perk, Phoebe is singing a new song as the gang looks on.</em></p><blockquote><p>🎬 <em>中央公园，菲比正在唱一首新歌，这帮人正在观看。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S06/S06E15.mp3`,start:`2202.648`,duration:`0.984`}),c[2189]||=o(` <strong>Phoebe Buffay:</strong> (singing)<blockquote><p>（唱歌）</p></blockquote><p>It only takes two heart attacks to finally make you see…</p><blockquote><p>只要两次心脏病发作，你就会明白…</p></blockquote><p>One of them won’t do it, but the second one will set you free…</p><blockquote><p>其中一个不会，但第二个会让你自由…</p></blockquote><p>Tell all your hate and anger, it’s time to say good-bye…</p><blockquote><p>告诉你所有的仇恨和愤怒，是时候说再见了…</p></blockquote><p>And that is just what I will do, soon as those bastards I work for die!</p><blockquote><p>这就是我要做的，只要我为之工作的那些混蛋死了！</p></blockquote><p>La, la-la-la, la-la-la-la, la-la-la, la-la-la……</p><blockquote><p>拉拉，拉拉，拉拉，拉拉，拉拉……</p></blockquote>`,14)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};